190	      _err("Failed to mount procfs at /proc: %d\n", ret);
191	    }
192	#endif
193	
194	#ifdef CONFIG_FS_TMPFS
195	  /* Mount the tmpfs file system */
196	
197	  ret = nx_mount(NULL, CONFIG_LIBC_TMPDIR, "tmpfs", 0, NULL);
198	  if (ret < 0)
199	    {
200	      _err("Failed to mount tmpfs at %s: %d\n", CONFIG_LIBC_TMPDIR, ret);
201	    }
202	#endif
203	
204	#if defined(CONFIG_ESPRESSIF_EFUSE)
205	  ret = esp_efuse_initialize("/dev/efuse");
206	  if (ret < 0)
207	    {
208	      syslog(LOG_ERR, "ERROR: Failed to init EFUSE: %d\n", ret);
209	    }
210	#endif
211	
212	#ifdef CONFIG_ESPRESSIF_MWDT0
213	  ret = esp_wdt_initialize("/dev/watchdog0", ESP_WDT_MWDT0);
214	  if (ret < 0)
215	    {
216	      _err("Failed to initialize WDT: %d\n", ret);
217	    }
218	#endif
219	
220	#ifdef CONFIG_ESPRESSIF_MWDT1
221	  ret = esp_wdt_initialize("/dev/watchdog1", ESP_WDT_MWDT1);
222	  if (ret < 0)
