2	 * esp32p4_wifi.c
3	 *
4	 * WiFi driver using esp_hosted protocol over SDIO.
5	 * ESP32-P4 (host) <-> SDIO <-> ESP32-C6 (WiFi co-processor)
6	 *
7	 * SPDX-License-Identifier: Apache-2.0
8	 ****************************************************************************/
9	
