29	/****************************************************************************
30	 * Pre-processor Definitions
31	 ****************************************************************************/
32	
33	#define WIFI_TAG "wifi"
34	#define WIFI_ERR(...)  syslog(LOG_ERR, WIFI_TAG ": " __VA_ARGS__)
35	#define WIFI_INFO(...) syslog(LOG_INFO, WIFI_TAG ": " __VA_ARGS__)
36	#define WIFI_DBG(...)  syslog(LOG_DEBUG, WIFI_TAG ": " __VA_ARGS__)
37	
38	/* esp_hosted control commands (sent over control channel) */
39	
40	#define ESP_HOSTED_CMD_INIT          0x01
41	#define ESP_HOSTED_CMD_SCAN          0x02
42	#define ESP_HOSTED_CMD_CONNECT       0x03
43	#define ESP_HOSTED_CMD_DISCONNECT    0x04
44	#define ESP_HOSTED_CMD_GET_MAC       0x05
45	#define ESP_HOSTED_CMD_GET_STATUS    0x06
46	
47	/* esp_hosted control responses */
48	
49	#define ESP_HOSTED_RESP_OK           0x00
50	#define ESP_HOSTED_RESP_ERROR        0x01
51	#define ESP_HOSTED_RESP_SCAN_RESULT  0x02
52	
53	/* esp_hosted control message format */
54	
55	#define ESP_HOSTED_CTRL_MSG_HDR_LEN  4
56	
57	/* WiFi status */
58	
59	#define WIFI_STATUS_DISCONNECTED     0
60	#define WIFI_STATUS_CONNECTED        1
61	
62	/* Work queue timing */
63	
64	#define WIFI_POLL_INTERVAL   MSEC2TICK(50)
65	#define WIFI_CONNECT_TIMEOUT MSEC2TICK(10000)
66	
67	/* Maximum scan results */
68	
69	#define MAX_SCAN_RESULTS     16
70	#define MAX_SSID_LEN         32
71	
72	/****************************************************************************
73	 * Private Types
74	 ****************************************************************************/
75	
76	/* Control message header */
77	
78	struct esp_hosted_ctrl_msg_s
79	{
80	  uint8_t  cmd;      /* Command type */
81	  uint8_t  status;   /* Response status */
82	  uint16_t len;      /* Payload length */
83	};
84	
85	/* Scan result entry */
86	
87	struct esp_hosted_scan_result_s
88	{
89	  uint8_t  ssid[MAX_SSID_LEN];
90	  uint8_t  ssid_len;
91	  int8_t   rssi;
92	  uint8_t  auth_mode;
93	  uint8_t  channel;
94	  uint8_t  bssid[6];
95	};
