98	
99	struct esp_wifi_dev_s
100	{
101	  struct net_driver_s  netdev;           /* NuttX network device */
102	  struct work_s        pollwork;         /* Deferred poll work */
103	  bool                 ifup;            /* Interface is up */
104	  bool                 connected;       /* WiFi connected */
105	  uint8_t              mac[6];          /* MAC address */
106	  uint8_t              rxbuf[1600];     /* Receive buffer */
107	  uint8_t              ctrlbuf[512];    /* Control message buffer */
108	  char                 ssid[MAX_SSID_LEN + 1]; /* Current SSID */
109	  char                 password[64];    /* Current password */
110	  uint8_t              status;          /* WiFi status */
111	  mutex_t              lock;            /* Thread safety */
112	  struct esp_hosted_scan_result_s scan_results[MAX_SCAN_RESULTS];
113	  int                  scan_count;
114	};
