423	#ifdef CONFIG_NETDEV_IOCTL
424	static int esp_wifi_ioctl(FAR struct net_driver_s *dev, int cmd,
425	                          unsigned long arg)
426	{
427	  FAR struct esp_wifi_dev_s *priv =
428	    (FAR struct esp_wifi_dev_s *)dev->d_private;
429	  int ret = -ENOTTY;
430	
431	  /* Handle standard wireless ioctls */
432	
433	  switch (cmd)
434	    {
435	      case 0x8B19: /* SIOCSIWSCAN - Initiate scan */
436	        ret = esp_wifi_do_scan();
437	        break;
438	
439	      case 0x8B1A: /* SIOCGIWSCAN - Get scan results */
440	        {
441	          /* Return scan count as the result */
442	
443	          ret = priv->scan_count;
444	        }
445	        break;
446	
447	      case 0x8B1B: /* SIOCSIWESSID - Set ESSID (connect) */
448	        {
449	          /* arg points to a buffer with the SSID */
450	
451	          if (arg != 0)
452	            {
453	              const char *ssid = (const char *)arg;
454	              ret = esp_wifi_do_connect(ssid, priv->password);
455	            }
456	        }
457	        break;
458	
459	      case 0x8B1C: /* SIOCGIWESSID - Get ESSID */
460	        {
461	          if (arg != 0)
462	            {
463	              char *buf = (char *)arg;
464	              strncpy(buf, priv->ssid, MAX_SSID_LEN);
465	              ret = OK;
466	            }
467	        }
468	        break;
469	
470	      case 0x8B20: /* SIOCSIWAUTH - Set auth */
471	        ret = OK;
472	        break;
473	
474	      case 0x8B2A: /* SIOCSIWENCODEEXT - Set key */
475	        {
476	          /* Store password for later connect */
477	
478	          if (arg != 0)
479	            {
480	              const char *key = (const char *)arg;
481	              strncpy(priv->password, key, sizeof(priv->password) - 1);
482	              ret = OK;
483	            }
484	        }
485	        break;
486	
487	      case 0x8B30: /* SIOCSIWDISPRIV - Disconnect */
488	        ret = esp_wifi_do_disconnect();
489	        break;
490	
491	      default:
492	        WIFI_DBG("Unknown ioctl 0x%x\n", cmd);
493	        break;
494	    }
495	
496	  return ret;
497	}
498	#endif /* CONFIG_NETDEV_IOCTL */
