437	/****************************************************************************
438	 * Name: sdio_init_hw
439	 *
440	 * Description:
441	 *   Initialize the ESP32-P4 SDMMC hardware for SDIO communication.
442	 *
443	 ****************************************************************************/
444	
445	static int sdio_init_hw(void)
446	{
447	  volatile uint32_t *clk_rst_reg;
448	  int timeout;
449	  uint32_t resp;
450	  int ret;
451	
452	  up_puts("SDIO: init_hw start\n");
453	
454	  /* Step 1: Enable SDMMC peripheral clock
455	   * ESP32-P4: HP_SYS_CLKRST_BASE = 0x500E6000
456	   * soc_clk_ctrl1 is at offset 0x04
457	   */
458	
459	  clk_rst_reg = (volatile uint32_t *)0x500E6004;
460	  *clk_rst_reg |= (1 << 12);  /* Enable SDMMC clock */
461	  up_puts("SDIO: clock enabled\n");
462	
463	  /* Step 2: Configure GPIO pins for SDIO2 via GPIO matrix
464	   * User-provided pin mapping:
465	   *   SD2 D0  = GPIO14
466	   *   SD2 D1  = GPIO15
467	   *   SD2 D2  = GPIO16
468	   *   SD2 D3  = GPIO17
469	   *   SD2 CLK = GPIO18
470	   *   SD2 CMD = GPIO19
471	   *
472	   * ESP32-P4 GPIO matrix: each GPIO has a FUNCx_OUT_SEL_CFG register
473	   * at GPIO_BASE + 0x554 + gpio*4 for output routing.
474	   * SDMMC SLOT1 signal indices:
475	   *   SDMMC_CCLK_IN = 0, SDMMC_CMD  = 1, SDMMC_D0 = 2,
476	   *   SDMMC_D1 = 3, SDMMC_D2 = 4, SDMMC_D3 = 5
477	   */
478	
479	#define GPIO_BASE           0x500E0000
480	#define GPIO_FUNC_OUT_SEL   (GPIO_BASE + 0x554)  /* FUNCx_OUT_SEL_CFG */
481	#define GPIO_FUNC_IN_SEL    (GPIO_BASE + 0x154)  /* FUNCx_IN_SEL_CFG  */
482	#define GPIO_ENABLE_W1TS    (GPIO_BASE + 0x20)   /* Output enable set  */
483	
484	  /* SDMMC SLOT1 signal indices (from ESP32-P4 TRM) */
485	
486	#define SDMMC_SLOT1_D0   58
487	#define SDMMC_SLOT1_D1   59
488	#define SDMMC_SLOT1_D2   60
489	#define SDMMC_SLOT1_D3   61
490	#define SDMMC_SLOT1_CLK  56
491	#define SDMMC_SLOT1_CMD  57
492	
493	  /* Configure GPIO14-19 as SDMMC SLOT1 signals */
494	
495	  volatile uint32_t *func_out;
496	  volatile uint32_t *enable;
497	
498	  /* GPIO14 -> SDMMC SLOT1 D0 */
499	
500	  func_out = (volatile uint32_t *)(GPIO_FUNC_OUT_SEL + 14 * 4);
501	  *func_out = SDMMC_SLOT1_D0;
502	  enable = (volatile uint32_t *)(GPIO_ENABLE_W1TS);
503	  *enable = (1 << 14);
504	
505	  /* GPIO15 -> SDMMC SLOT1 D1 */
506	
507	  func_out = (volatile uint32_t *)(GPIO_FUNC_OUT_SEL + 15 * 4);
508	  *func_out = SDMMC_SLOT1_D1;
509	  *enable = (1 << 15);
510	
511	  /* GPIO16 -> SDMMC SLOT1 D2 */
512	
513	  func_out = (volatile uint32_t *)(GPIO_FUNC_OUT_SEL + 16 * 4);
514	  *func_out = SDMMC_SLOT1_D2;
515	  *enable = (1 << 16);
516	
517	  /* GPIO17 -> SDMMC SLOT1 D3 */
518	
519	  func_out = (volatile uint32_t *)(GPIO_FUNC_OUT_SEL + 17 * 4);
520	  *func_out = SDMMC_SLOT1_D3;
521	  *enable = (1 << 17);
522	
523	  /* GPIO18 -> SDMMC SLOT1 CLK */
524	
525	  func_out = (volatile uint32_t *)(GPIO_FUNC_OUT_SEL + 18 * 4);
526	  *func_out = SDMMC_SLOT1_CLK;
527	  *enable = (1 << 18);
528	
529	  /* GPIO19 -> SDMMC SLOT1 CMD */
530	
531	  func_out = (volatile uint32_t *)(GPIO_FUNC_OUT_SEL + 19 * 4);
532	  *func_out = SDMMC_SLOT1_CMD;
533	  *enable = (1 << 19);
534	
535	  up_puts("SDIO: GPIO configured\n");
536	
537	  /* Step 3: Reset the SDMMC controller
538	   * CTRL register bit 0: controller_reset
539	   * bit 1: fifo_reset
540	   * bit 2: dma_reset
541	   */
542	
543	  volatile uint32_t *ctrl = (volatile uint32_t *)SDMMC_CTRL;
544	  *ctrl = 0x7;  /* Reset controller + FIFO + DMA */
545	  up_mdelay(10);
546	
547	  /* Wait for reset to complete (bits auto-clear) */
548	
549	  int rst_timeout = 100;
550	  while ((*ctrl & 0x7) && rst_timeout-- > 0)
551	    {
552	      up_mdelay(1);
553	    }
554	
555	  up_puts("SDIO: controller reset done\n");
556	
557	  /* Step 4: Configure clock for identification mode (400kHz)
558	   * Source clock = 160MHz (ESP32-P4 default)
559	   * Divider = 160MHz / 400kHz / 2 = 200
560	   * CLKDIV register: divider = (div_factor << 8) | div_factor_half
561	   * For 400kHz: div_factor = 200
562	   */
563	
564	  volatile uint32_t *clkdiv = (volatile uint32_t *)SDMMC_CLKDIV;
565	  *clkdiv = (200 << 8) | 200;  /* Divide by 200 */
566	
567	  volatile uint32_t *clksrc = (volatile uint32_t *)SDMMC_CLKSRC;
568	  *clksrc = 0;  /* Use divider 0 */
569	
570	  /* Enable clock */
571	
572	  volatile uint32_t *clkena = (volatile uint32_t *)SDMMC_CLKENA;
573	  *clkena = 0x1;  /* Enable clock for card */
574	
575	  /* Set timeout */
576	
577	  volatile uint32_t *tmout = (volatile uint32_t *)SDMMC_TMOUT;
578	  *tmout = (0xFFFFFF << 8) | 0x64;  /* Response timeout + data timeout */
579	
580	  /* Set card type to 1-bit mode */
581	
582	  volatile uint32_t *ctype = (volatile uint32_t *)SDMMC_CTYPE;
583	  *ctype = 0;  /* 1-bit mode */
584	
585	  /* Step 5: Send CMD0 (GO_IDLE_STATE) */
586	
587	  ret = sdio_send_cmd(SDIO_CMD_GO_IDLE_STATE, 0, NULL, SDIO_RESP_NONE);
588	  up_puts("SDIO: CMD0 done\n");
589	  if (ret < 0)
590	    {
591	      up_puts("SDIO: CMD0 failed\n");
592	      return ret;
593	    }
594	
595	  up_mdelay(10);
596	
597	  /* Step 6: Send CMD5 (IO_SEND_OP_COND) to detect SDIO card
598	   * For esp_hosted, CMD5 query success means the card is present.
599	   * We don't need to wait for bit 31 - just proceed.
600	   */
601	
602	  ret = sdio_send_cmd(SDIO_CMD_SEND_OP_COND, 0, &resp, SDIO_RESP_R4);
603	  if (ret < 0)
604	    {
605	      up_puts("SDIO: CMD5 query FAIL\n");
606	      return ret;
607	    }
608	
609	  up_puts("SDIO: CMD5 query OK\n");
610	
611	  /* Send CMD5 with voltage window to power up (best effort) */
612	
613	  ret = sdio_send_cmd(SDIO_CMD_SEND_OP_COND, 0x00FF8000,
614	                      &resp, SDIO_RESP_R4);
615	  up_mdelay(10);
616	
617	  if (timeout <= 0)
618	    {
619	      SDIO_ERR("SDIO card not ready\n");
620	      return -ETIMEDOUT;
621	    }
622	
623	  /* Step 7: Send CMD3 (SEND_RELATIVE_ADDR) to get RCA */
624	
625	  ret = sdio_send_cmd(SDIO_CMD_SEND_RELATIVE_ADDR, 0, &resp, SDIO_RESP_R6);
626	  if (ret < 0)
627	    {
628	      SDIO_ERR("CMD3 failed: %d\n", ret);
629	      return ret;
630	    }
631	
632	  g_sdio.rca = (resp >> 16) & 0xFFFF;
633	  up_puts("SDIO: CMD3 done\n");
634	
635	  /* Step 8: Send CMD7 (SELECT_CARD) to select the card */
636	
637	  ret = sdio_send_cmd(SDIO_CMD_SELECT_CARD,
638	                      ((uint32_t)g_sdio.rca) << 16,
639	                      &resp, SDIO_RESP_R6);
640	  if (ret < 0)
641	    {
642	      SDIO_ERR("CMD7 failed: %d\n", ret);
643	      return ret;
644	    }
645	
646	  up_puts("SDIO: CMD7 done\n");
647	
648	  /* Step 9: Enable SDIO function 1 (used by esp_hosted) */
649	
650	  ret = sdio_cmd52_write(0, SDIO_CCCR_IO_ENABLE, 0x02, NULL);
651	  if (ret < 0)
652	    {
653	      SDIO_ERR("Failed to enable SDIO function 1: %d\n", ret);
654	      return ret;
655	    }
656	
657	  /* Wait for function 1 to be ready */
658	
659	  timeout = SDIO_CMD_TIMEOUT_MS;
660	  while (timeout-- > 0)
661	    {
662	      uint8_t ready;
663	      ret = sdio_cmd52_read(0, SDIO_CCCR_IO_READY, &ready);
664	      if (ret >= 0 && (ready & 0x02))
665	        {
666	          SDIO_INFO("SDIO function 1 ready\n");
667	          break;
668	        }
669	      up_mdelay(1);
670	    }
671	
672	  if (timeout <= 0)
673	    {
674	      SDIO_ERR("SDIO function 1 not ready\n");
675	      return -ETIMEDOUT;
676	    }
677	
678	  /* Step 10: Set bus width to 4-bit */
679	
680	  ret = sdio_cmd52_write(0, SDIO_CCCR_BUS_CTRL, 0x02, NULL);
681	  if (ret < 0)
682	    {
683	      SDIO_ERR("Failed to set 4-bit bus width: %d\n", ret);
684	      /* Not fatal, continue with 1-bit mode */
685	    }
686	  else
687	    {
688	      SDIO_INFO("4-bit bus width enabled\n");
689	    }
690	
691	  /* Step 11: Increase clock speed to operational frequency */
692	
693	  /* TODO: Set clock to CONFIG_ESP32P4_WIFI_HOSTED_SDIO_FREQ */
694	
695	  up_puts("SDIO: init OK\n");
696	  return OK;
697	}
