53	// workarounds for known ESP-IDF SDMMC issues
54	static void hosted_sdio_workaround(int slot, sdmmc_slot_config_t *slot_config)
55	{
56		if (slot == 0) {
57	#if !SDMMC_LL_SLOT_SUPPORT_GPIO_MATRIX(0)
58			/* workaround for 1-bit mode on Slot 0 with IOMUX only pins:
59			 * set gpio pins D2, D3 to pass sdmmc_host.c->sdmmc_host_init_slot() IOMUX GPIO checking
60			 */
61			if (slot_config->width == 1) {
62				ESP_LOGW(TAG, "workaround: setting D2-D3 in 1 bit mode for slot %d", slot);
63				slot_config->d2 = SDMMC_SLOT0_IOMUX_PIN_NUM_D2;
64				slot_config->d3 = SDMMC_SLOT0_IOMUX_PIN_NUM_D3;
65			}
66	#endif
67		}
68	}
