89	static esp_err_t hosted_sdio_print_cis_information(sdmmc_card_t* card)
90	{
91		uint8_t cis_buffer[CIS_BUFFER_SIZE];
92		size_t cis_data_len = 1024; //specify maximum searching range to avoid infinite loop
93		esp_err_t ret = ESP_OK;
94	
95		SDIO_FAIL_IF_NULL(card);
96	
97		ret = sdmmc_io_get_cis_data(card, cis_buffer, CIS_BUFFER_SIZE, &cis_data_len);
98		if (ret == ESP_ERR_INVALID_SIZE) {
99			int temp_buf_size = cis_data_len;
100			uint8_t* temp_buf = g_h.funcs->_h_malloc(temp_buf_size);
101			assert(temp_buf);
102	
103			ESP_LOGW(TAG, "CIS data longer than expected, temporary buffer allocated.");
104			ret = sdmmc_io_get_cis_data(card, temp_buf, temp_buf_size, &cis_data_len);
105			if (ret != ESP_OK) {
106				ESP_LOGE(TAG, "failed to get CIS data.");
107				HOSTED_FREE(temp_buf);
108				return ret;
109			}
110	
111			sdmmc_io_print_cis_info(temp_buf, cis_data_len, NULL);
112	
113			HOSTED_FREE(temp_buf);
114		} else if (ret == ESP_OK) {
115			sdmmc_io_print_cis_info(cis_buffer, cis_data_len, NULL);
116		} else {
117			ESP_LOGE(TAG, "failed to get CIS data.");
118			return ret;
119		}
120		return ESP_OK;
121	}
