123	static esp_err_t hosted_sdio_set_blocksize(sdmmc_card_t *card, uint8_t fn, uint16_t value)
124	{
125		size_t offset = SD_IO_FBR_START * fn;
126		const uint8_t *bs_u8 = (const uint8_t *) &value;
127		uint16_t bs_read = 0;
128		uint8_t *bs_read_u8 = (uint8_t *) &bs_read;
129	
130		// Set and read back block size
131		ESP_ERROR_CHECK(sdmmc_io_write_byte(card, SDIO_FUNC_0, offset + SD_IO_CCCR_BLKSIZEL, bs_u8[0], NULL));
132		ESP_ERROR_CHECK(sdmmc_io_write_byte(card, SDIO_FUNC_0, offset + SD_IO_CCCR_BLKSIZEH, bs_u8[1], NULL));
133		ESP_ERROR_CHECK(sdmmc_io_read_byte(card, SDIO_FUNC_0, offset + SD_IO_CCCR_BLKSIZEL, &bs_read_u8[0]));
134		ESP_ERROR_CHECK(sdmmc_io_read_byte(card, SDIO_FUNC_0, offset + SD_IO_CCCR_BLKSIZEH, &bs_read_u8[1]));
135		ESP_LOGI(TAG, "Function %d Blocksize: %d", fn, (unsigned int) bs_read);
136	
137		if (bs_read == value)
138			return ESP_OK;
139		else
140			return ESP_FAIL;
141	}
