143	static esp_err_t hosted_sdio_card_fn_init(sdmmc_card_t *card)
144	{
145		uint8_t ioe = 0;
146		uint8_t ior = 0;
147		uint8_t ie = 0;
148		uint8_t bus_width = 0;
149		uint16_t bs = 0;
150		int i = 0;
151	
152		SDIO_FAIL_IF_NULL(card);
153	
154		/** initial register reads may fail if SDIO device is not yet ready
155		 * return ESP_FAIL to let upper layers retry card init
156		 */
157		if (ESP_OK != sdmmc_io_read_byte(card, SDIO_FUNC_0, SD_IO_CCCR_FN_ENABLE, &ioe))
158			return ESP_FAIL;
159	
160		ESP_LOGD(TAG, "IOE: 0x%02x", ioe);
161	
162		if (ESP_OK != sdmmc_io_read_byte(card, SDIO_FUNC_0, SD_IO_CCCR_FN_READY, &ior))
163			return ESP_FAIL;
164	
165		ESP_LOGD(TAG, "IOR: 0x%02x", ior);
166	
167		// enable function 1
168		ioe |= FUNC1_EN_MASK;
169		if (ESP_OK != sdmmc_io_write_byte(card, SDIO_FUNC_0, SD_IO_CCCR_FN_ENABLE, ioe, &ioe))
170			return ESP_FAIL;
171		ESP_LOGD(TAG, "IOE: 0x%02x", ioe);
172	
173		if (ESP_OK != sdmmc_io_read_byte(card, SDIO_FUNC_0, SD_IO_CCCR_FN_ENABLE, &ioe))
174			return ESP_FAIL;
175		ESP_LOGD(TAG, "IOE: 0x%02x", ioe);
176	
177		// wait for the card to become ready
178		ior = 0;
179		for (i = 0; i < SDIO_INIT_MAX_RETRY; i++) {
180			if (ESP_OK != sdmmc_io_read_byte(card, SDIO_FUNC_0, SD_IO_CCCR_FN_READY, &ior))
181				return ESP_FAIL;
182			ESP_LOGD(TAG, "IOR: 0x%02x", ior);
183			if (ior & FUNC1_EN_MASK) {
184				break;
185			} else {
186				usleep(10 * 1000);
187			}
188		}
189		if (i >= SDIO_INIT_MAX_RETRY) {
190			// card failed to become ready
191			return ESP_FAIL;
192		}
193	
194		// get interrupt status
195		ESP_ERROR_CHECK(sdmmc_io_read_byte(card, SDIO_FUNC_0, SD_IO_CCCR_INT_ENABLE, &ie));
196		ESP_LOGD(TAG, "IE: 0x%02x", ie);
197	
198		// enable interrupts for function 1 and master enable
199		ie |= BIT(0) | FUNC1_EN_MASK;
200		ESP_ERROR_CHECK(sdmmc_io_write_byte(card, SDIO_FUNC_0, SD_IO_CCCR_INT_ENABLE, ie, NULL));
201	
202		ESP_ERROR_CHECK(sdmmc_io_read_byte(card, SDIO_FUNC_0, SD_IO_CCCR_INT_ENABLE, &ie));
203		ESP_LOGD(TAG, "IE: 0x%02x", ie);
204	
205		// get bus width register
206		ESP_ERROR_CHECK(sdmmc_io_read_byte(card, SDIO_FUNC_0, SD_IO_CCCR_BUS_WIDTH, &bus_width));
207		ESP_LOGD(TAG, "BUS_WIDTH: 0x%02x", bus_width);
208	
209		// skip enable of continuous SPI interrupts
210	
211		// set FN0 block size to 512
212		bs = 512;
213		ESP_ERROR_CHECK(hosted_sdio_set_blocksize(card, SDIO_FUNC_0, bs));
214	
215		// set FN1 block size to 512
216		bs = 512;
217		ESP_ERROR_CHECK(hosted_sdio_set_blocksize(card, SDIO_FUNC_1, bs));
218	
219		return ESP_OK;
220	}
