222	static esp_err_t sdio_read_fromio(sdmmc_card_t *card, uint32_t function, uint32_t addr,
223								uint8_t *data, uint16_t size)
224	{
225		uint16_t remainder = size;
226		uint16_t blocks;
227		esp_err_t res;
228		uint8_t *ptr = data;
229	
230		// do block mode transfer
231		while (remainder >= ESP_BLOCK_SIZE) {
232			blocks = H_SDIO_RX_BLOCKS_TO_TRANSFER(remainder);
233			size = blocks * ESP_BLOCK_SIZE;
234			res = sdmmc_io_read_blocks(card, function, addr, ptr, size);
235			if (res)
236				return res;
237	
238			remainder -= size;
239			ptr += size;
240			addr += size;
241		}
242	
243		// transfer remainder using byte mode
244		while (remainder > 0) {
245			size = remainder;
246			res = sdmmc_io_read_bytes(card, function, addr, ptr, size);
247			if (res)
248				return res;
249	
250			remainder -= size;
251			ptr += size;
252			addr += size;
253		}
254	
255		return ESP_OK;
256	}
