268			blocks = H_SDIO_TX_BLOCKS_TO_TRANSFER(remainder);
269			size = blocks * ESP_BLOCK_SIZE;
270			res = sdmmc_io_write_blocks(card, function, addr, ptr, size);
271			if (res)
272				return res;
273	
274			remainder -= size;
275			ptr += size;
276			addr += size;
277		}
278	
279		// transfer remainder using byte mode
280		while (remainder > 0) {
281			size = remainder;
282			res = sdmmc_io_write_bytes(card, function, addr, ptr, size);
283			if (res)
