317	void * hosted_sdio_init(void)
318	{
319		esp_err_t res;
320		bool got_valid_config = false;
321	
322		/* Guard against multiple initialization */
323		if (sdio_bus_lock) {
324			ESP_LOGW(TAG, "SDIO already initialized, skipping");
325			return (void *)&context;
326		}
327	
328		sdmmc_slot_config_t slot_config = SDMMC_SLOT_CONFIG_DEFAULT();
329	
330		if (esp_hosted_transport_is_config_valid()) {
331			// copy sdio config if valid
332			struct esp_hosted_transport_config *pconfig;
333	
334			if (ESP_TRANSPORT_OK == esp_hosted_transport_get_config(&pconfig)) {
335				if (pconfig->transport_in_use == H_TRANSPORT_SDIO) {
336					struct esp_hosted_sdio_config *psdio_config;
337	
338					if (ESP_TRANSPORT_OK == esp_hosted_sdio_get_config(&psdio_config)) {
339						// copy transport config
340						g_h.funcs->_h_memcpy(&context.config, psdio_config, sizeof(struct esp_hosted_sdio_config));
341						got_valid_config = true;
342					}
343				} else {
344					ESP_LOGE(TAG, "transport config is not for SDIO: ignoring");
345				}
346			}
347		}
348		if (!got_valid_config) {
349			// no valid transport config: use values from esp_hosted_config.h
350			context.config.clock_freq_khz = H_SDIO_CLOCK_FREQ_KHZ;
351			context.config.bus_width      = H_SDIO_BUS_WIDTH;
352			context.config.slot           = H_SDMMC_HOST_SLOT;
353			context.config.pin_clk.pin    = H_SDIO_PIN_CLK;
354			context.config.pin_cmd.pin    = H_SDIO_PIN_CMD;
355			context.config.pin_d0.pin     = H_SDIO_PIN_D0;
356			context.config.pin_d1.pin     = H_SDIO_PIN_D1;
357			context.config.pin_d2.pin     = H_SDIO_PIN_D2;
358			context.config.pin_d3.pin     = H_SDIO_PIN_D3;
359		}
360	
361		// initialise SDMMC host
362		res = sdmmc_host_init();
363		if (res != ESP_OK) {
364			ESP_LOGE(TAG, "Failed to initialize SDMMC host");
365			return NULL;
366		}
367	
368		// configure SDIO interface and slot
369		slot_config.width = context.config.bus_width;
370	#if defined(H_SDIO_SOC_USE_GPIO_MATRIX)
371		slot_config.clk = context.config.pin_clk.pin;
372		slot_config.cmd = context.config.pin_cmd.pin;
373		slot_config.d0  = context.config.pin_d0.pin;
374		slot_config.d1  = context.config.pin_d1.pin;
375		slot_config.d2  = context.config.pin_d2.pin;
376		slot_config.d3  = context.config.pin_d3.pin;
377	#endif
378	
379		hosted_sdio_workaround(context.config.slot, &slot_config);
380	
381		res = sdmmc_host_init_slot(context.config.slot, &slot_config);
382		if (res != ESP_OK) {
383			ESP_LOGE(TAG, "init SDMMC Host slot %d failed", H_SDMMC_HOST_SLOT);
384			return NULL;
385		}
386	
387		// initialise connected SDIO card/slave
388		context.card = (sdmmc_card_t *)g_h.funcs->_h_malloc(sizeof(sdmmc_card_t));
389		if (!context.card) {
390			ESP_LOGE(TAG, "Failed to allocate memory for SDMMC card");
391			return NULL;
392		}
393	
394		// initialise mutex for bus locking
395		sdio_bus_lock = g_h.funcs->_h_create_mutex();
396		assert(sdio_bus_lock);
397	
398		return (void *)&context;
399	}
