401	int hosted_sdio_card_init(void *ctx, bool show_config)
402	{
403		SDIO_FAIL_IF_NULL(ctx);
404	
405		sdmmc_context_t *context = (sdmmc_context_t *)ctx;
406	
407		struct esp_hosted_sdio_config *sdio_config = &context->config;
408		SDIO_FAIL_IF_NULL(sdio_config);
409		SDIO_FAIL_IF_NULL(context->card);
410	
411		sdmmc_host_t config = SDMMC_HOST_DEFAULT();
412		config.slot = sdio_config->slot; // override default slot set
413	
414		if (!hosted_sdio_enable_ldo(&config)) {
415			goto fail;
416		}
417	
418		config.max_freq_khz = sdio_config->clock_freq_khz;
419		if (show_config) {
420			ESP_LOGI(TAG, "SDIO master: Slot %d, Data-Lines: %d-bit Freq(KHz)[%u KHz]",
421					config.slot,
422					sdio_config->bus_width==4? 4:1,
423					config.max_freq_khz);
424			if (sdio_config->bus_width == 4) {
425				ESP_LOGI(TAG, "GPIOs: CLK[%u] CMD[%u] D0[%u] D1[%u] D2[%u] D3[%u] Slave_Reset[%u]",
426						sdio_config->pin_clk.pin, sdio_config->pin_cmd.pin,
427						sdio_config->pin_d0.pin, sdio_config->pin_d1.pin,
428						sdio_config->pin_d2.pin, sdio_config->pin_d3.pin,
429						sdio_config->pin_reset.pin);
430			} else {
431				ESP_LOGI(TAG, "GPIOs: CLK[%u] CMD[%u] D0[%u] D1[%u] Slave_Reset[%u]",
432						sdio_config->pin_clk.pin, sdio_config->pin_cmd.pin,
433						sdio_config->pin_d0.pin, sdio_config->pin_d1.pin,
434						sdio_config->pin_reset.pin);
435			}
436			ESP_LOGI(TAG, "Queues: Tx[%u] Rx[%u] SDIO-Rx-Mode[%u]",
437					sdio_config->tx_queue_size, sdio_config->rx_queue_size,
438					sdio_config->rx_mode);
439		}
440	
441	#ifdef CONFIG_IDF_TARGET_ESP32P4
442		// Set this flag to allocate aligned buffer of 512 bytes to meet
443		// DMA's requirements for CMD53 byte mode. Mandatory when any
444		// buffer is behind the cache, or not aligned to 4 byte boundary.
445		config.flags |= SDMMC_HOST_FLAG_ALLOC_ALIGNED_BUF;
446	#endif
447	
448		if (sdmmc_card_init(&config, context->card) != ESP_OK) {
449			ESP_LOGE(TAG, "sdmmc_card_init failed");
450			goto fail;
451		}
452	
453		if (esp_log_level_get(TAG) >= ESP_LOG_DEBUG) {
454			// output CIS info from the slave
455			sdmmc_card_print_info(stdout, context->card);
456	
457			if (hosted_sdio_print_cis_information(context->card) != ESP_OK) {
458				ESP_LOGW(TAG, "failed to print card info");
459			}
460		}
461	
462		// initialise the card functions
463		if (hosted_sdio_card_fn_init(context->card) != ESP_OK) {
464			ESP_LOGE(TAG, "sdio_card_fn_init failed");
465			goto fail;
466		}
467		return ESP_OK;
468	
469	fail:
470		return ESP_FAIL;
471	}
472	
473	int hosted_sdio_card_deinit(void *ctx)
474	{
475		SDIO_FAIL_IF_NULL(ctx);
476	
477		sdmmc_context_t *context = (sdmmc_context_t *)ctx;
478	
479		/* Free the DMA aligned buffer allocated by sdmmc_allocate_aligned_buf()
480		 * ESP-IDF allocates this in sdmmc_card_init() but doesn't provide cleanup API */
481		if (context->card && context->card->host.dma_aligned_buffer) {
482			free(context->card->host.dma_aligned_buffer);
483			context->card->host.dma_aligned_buffer = NULL;
484		}
485	
486		return ESP_OK;
487	}
