489	int hosted_sdio_read_reg(void *ctx, uint32_t reg, uint8_t *data, uint16_t size, bool lock_required)
490	{
491		int res = 0;
492	
493		SDIO_FAIL_IF_NULL(ctx);
494	
495		sdmmc_context_t *context = (sdmmc_context_t *)ctx;
496		sdmmc_card_t *card = context->card;
497		SDIO_FAIL_IF_NULL(card);
498	
499		/* Need to apply address mask when reading/writing slave registers */
500		reg &= ESP_ADDRESS_MASK;
501		ESP_LOGV(TAG, "%s: reg[0x%" PRIx32"] size[%u]", __func__, reg, size);
502	
503		SDIO_LOCK(lock_required);
504		if (size <= 1) {
505			res = sdmmc_io_read_byte(card, SDIO_FUNC_1, reg, data);
506		} else {
507			res = sdmmc_io_read_bytes(card, SDIO_FUNC_1, reg, data, size);
508		}
509		SDIO_UNLOCK(lock_required);
510		return res;
511	}
