161	/* -------- Threads ---------- */
162	
163	void *hosted_thread_create(const char *tname, uint32_t tprio, uint32_t tstack_size, void (*start_routine)(void const *), void *sr_arg)
164	{
165		int task_created = RET_OK;
166	
167		if (!start_routine) {
168			ESP_LOGE(TAG, "start_routine is mandatory for thread create\n");
169			return NULL;
170		}
171	
172		thread_handle_t *thread_handle = (thread_handle_t *)hosted_malloc(
173				sizeof(thread_handle_t));
174		if (!thread_handle) {
175			ESP_LOGE(TAG, "Failed to allocate thread handle\n");
176			return NULL;
177		}
178	
179	#if H_DFLT_TASK_FROM_SPIRAM
180		StaticTask_t *task_buffer = heap_caps_calloc(1, sizeof(StaticTask_t), MALLOC_CAP_INTERNAL);
181		if (!task_buffer) {
182			ESP_LOGE(TAG, "Failed to allocate task buffer");
183			HOSTED_FREE(thread_handle);
184			return NULL;
185		}
186		StackType_t *thread_stack = heap_caps_malloc(tstack_size, MALLOC_CAP_SPIRAM);
187		if (!thread_stack) {
188			ESP_LOGE(TAG, "Failed to allocate thread stack");
189			heap_caps_free(task_buffer);
190			HOSTED_FREE(thread_handle);
191			return NULL;
192		}
193	
194		task_created = pdTRUE;
195		*thread_handle = xTaskCreateStatic((void (*)(void *))start_routine, tname, tstack_size, sr_arg, tprio, thread_stack, task_buffer);
196		if (!*thread_handle) {
197			heap_caps_free(thread_stack);
198			heap_caps_free(task_buffer);
199			task_created = pdFALSE;
200		}
201	#else
202		task_created = xTaskCreate((void (*)(void *))start_routine, tname, tstack_size, sr_arg, tprio, thread_handle);
203	#endif
204		if (!(*thread_handle)) {
205			ESP_LOGE(TAG, "Failed to create thread: %s\n", tname);
206			HOSTED_FREE(thread_handle);
207			return NULL;
208		}
209	
210		if (task_created != pdTRUE) {
211			ESP_LOGE(TAG, "Failed 2 to create thread: %s\n", tname);
212			HOSTED_FREE(thread_handle);
213			return NULL;
214		}
215	
216		return thread_handle;
217	}
218	
219	int hosted_thread_cancel(void *thread_handle)
220	{
221		//int ret = RET_OK;
222		thread_handle_t *thread_hdl = NULL;
223	
224		if (!thread_handle) {
225			ESP_LOGE(TAG, "Invalid thread handle\n");
226			return RET_INVALID;
227		}
228	
229		thread_hdl = (thread_handle_t *)thread_handle;
230	
231		vTaskDelete(*thread_hdl);
232	
233		HOSTED_FREE(thread_handle);
234		return RET_OK;
235	}
