669	/* Sample timer_handler looks like this:
670	 *
671	 * void expired(union sigval timer_data){
672	 *     struct mystruct *a = timer_data.sival_ptr;
673	 * 	ESP_LOGE(TAG, "Expired %u\n", a->mydata++);
674	 * }
675	 **/
676	
677	void *hosted_timer_start(const char *name, int duration_ms, int type,
678			void (*timeout_handler)(void *), void *arg)
679	{
680		struct timer_handle_t *timer_handle = NULL;
681		int ret = RET_OK;
682	
683		esp_hosted_timer_type_t esp_timer_type = type;
684	
685		ESP_LOGD(TAG, "Start the timer %u\n", duration_ms);
686		//os_timer_type timer_type = osTimerOnce;
687		//osTimerDef (timerNew, timeout_handler);
688		const esp_timer_create_args_t timerNew_args = {
689			.callback = timeout_handler,
690			/* argument specified here will be passed to timer callback function */
691			.arg = (void*) arg,
692			.name = name,
693		};
694	
695	
696		/* alloc */
697		timer_handle = (struct timer_handle_t *)hosted_malloc(
698				sizeof(struct timer_handle_t));
699		if (!timer_handle) {
700			ESP_LOGE(TAG, "Memory allocation failed for timer\n");
701			return NULL;
702		}
703	
704		/* create */
705		/*timer_handle->timer_id =
706				osTimerCreate(osTimer(timerNew),
707				timer_type, arg);*/
708		ret = esp_timer_create(&timerNew_args, &(timer_handle->timer_id));
709		if (ret || (!timer_handle->timer_id) ) {
710			ESP_LOGE(TAG, "Failed to create timer. Err 0x%X", ret);
711			HOSTED_FREE(timer_handle);
712			return NULL;
713		}
714	
715		/* Start depending upon timer type */
716		if (esp_timer_type == H_TIMER_TYPE_PERIODIC) {
717			ret = esp_timer_start_periodic(timer_handle->timer_id, MILLISEC_TO_MICROSEC(duration_ms));
718		} else if (esp_timer_type == H_TIMER_TYPE_ONESHOT) {
719			ret = esp_timer_start_once(timer_handle->timer_id, MILLISEC_TO_MICROSEC(duration_ms));
720		} else {
721			ESP_LOGE(TAG, "Unsupported timer type. supported: one_shot, periodic\n");
722			esp_timer_delete(timer_handle->timer_id);
723			HOSTED_FREE(timer_handle);
724			return NULL;
725		}
726		/* This is a workaround to kick the timer task to pick up the timer */
727		vTaskDelay(100);
728	
729		if (ret) {
730			esp_timer_delete(timer_handle->timer_id);
731			HOSTED_FREE(timer_handle);
732			return NULL;
733		}
734	
735		return timer_handle;
736	}
