760	int hosted_setup_gpio_interrupt(void* gpio_port, uint32_t gpio_num, uint32_t intr_type, void (*fn)(void *), void *arg)
761	{
762		int ret = 0;
763		static bool isr_service_installed = false;
764	
765		gpio_config_t new_gpio_io_conf={
766			.mode=GPIO_MODE_INPUT,
767			.intr_type = GPIO_INTR_DISABLE,
768			.pin_bit_mask=(1ULL<<gpio_num)
769		};
770	
771		if (intr_type == H_GPIO_INTR_NEGEDGE) {
772			new_gpio_io_conf.pull_up_en = 1;
773		} else {
774			new_gpio_io_conf.pull_down_en = 1;
775		}
776	
777		ESP_LOGI(TAG, "GPIO [%d] configuring as Interrupt", (int) gpio_num);
778	
779		ESP_ERROR_CHECK_WITHOUT_ABORT(gpio_config(&new_gpio_io_conf));
780	
781		if (!isr_service_installed) {
782			gpio_install_isr_service(0);
783			isr_service_installed = true;
784		}
785	
786	    gpio_isr_handler_remove(gpio_num);
787	    ESP_ERROR_CHECK_WITHOUT_ABORT(gpio_isr_handler_add(gpio_num, fn, arg));
788	
789	    ret = gpio_set_intr_type(gpio_num, intr_type);
790	    if (ret != ESP_OK) {
791	        gpio_isr_handler_remove(gpio_num);
792	        return ret;
793	    }
794	
795		ESP_ERROR_CHECK_WITHOUT_ABORT(gpio_intr_enable(gpio_num));
796		return ret;
797	}
