910	int hosted_get_host_wakeup_or_reboot_reason(void)
911	{
912	#if H_HOST_PS_ALLOWED
913		esp_reset_reason_t reboot_reason = esp_reset_reason();
914		uint8_t wakeup_due_to_gpio = 0;
915	
916	#if H_PRESENT_IN_ESP_IDF_6_0_0
917		uint32_t wakeup_causes = esp_sleep_get_wakeup_causes();
918		wakeup_due_to_gpio = (wakeup_causes & BIT(ESP_SLEEP_WAKEUP_GPIO));
919	#else
920		uint32_t wakeup_cause = esp_sleep_get_wakeup_cause();
921		wakeup_due_to_gpio = (wakeup_cause == ESP_SLEEP_WAKEUP_GPIO);
922	#endif
923	
924		if (reboot_reason == ESP_RST_POWERON) {
925			return HOSTED_WAKEUP_NORMAL_REBOOT;
926		} else if ((reboot_reason == ESP_RST_DEEPSLEEP) &&
927		    (wakeup_due_to_gpio)) {
928			return HOSTED_WAKEUP_DEEP_SLEEP;
