#include "port_esp_hosted_host_config.h"
#include "esp_hosted_os_abstraction.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* Handle types - map to NuttX types */

typedef void *thread_handle_t;
typedef void *queue_handle_t;
typedef void *semaphore_handle_t;
typedef void *mutex_handle_t;

/* GPIO port handle */

#define gpio_port_handle_t     (void *)
#define H_GPIO_PORT_DEFAULT    -1

/* GPIO pin state */

#define gpio_pin_state_t       int

/* Blocking constants */

#define HOSTED_BLOCKING        -1
#define HOSTED_NON_BLOCKING    0
#define HOSTED_BLOCK_MAX       -1

/* Return codes */

#define RET_OK                 0
#define RET_FAIL               -1
#define RET_INVALID            -2
#define RET_FAIL_MEM           -3
#define RET_FAIL4              -4
#define RET_FAIL_TIMEOUT       -5

/* Memory alignment */

#define HOSTED_MEM_ALIGNMENT_4   4
#define HOSTED_MEM_ALIGNMENT_32  32
#define HOSTED_MEM_ALIGNMENT_64  64

/* Time conversion */

#define MILLISEC_TO_SEC        1000
#define SEC_TO_MILLISEC(x)     (1000 * (x))
#define SEC_TO_MICROSEC(x)     (1000 * 1000 * (x))
#define MILLISEC_TO_MICROSEC(x) (1000 * (x))

/* Task configuration */

#define RPC_TASK_STACK_SIZE    (5 * 1024)
#define RPC_TASK_PRIO          23
#define DFLT_TASK_STACK_SIZE   (5 * 1024)
#define DFLT_TASK_PRIO         23

/* Hardware type enum */

enum hardware_type_e
{
  HARDWARE_TYPE_ESP32,
  HARDWARE_TYPE_OTHER_ESP_CHIPSETS,
  HARDWARE_TYPE_INVALID,
};

/* Memory macros */

#define HOSTED_FREE(buff) \
  do { \
    if (buff) { \
      g_h.funcs->_h_free(buff); \
      buff = NULL; \
    } \
  } while (0)

#define HOSTED_CALLOC(struct_name, buff, nbytes, gotosym) \
  do { \
    buff = (struct_name *)g_h.funcs->_h_calloc(1, nbytes); \
    if (!buff) { \
      goto gotosym; \
    } \
  } while (0)

#define HOSTED_MALLOC(struct_name, buff, nbytes, gotosym) \
  do { \
    buff = (struct_name *)g_h.funcs->_h_malloc(nbytes); \
    if (!buff) { \
      goto gotosym; \
    } \
  } while (0)

/* Maximum payload size */

#ifndef MAX_TRANSPORT_BUFFER_SIZE
#  define MAX_TRANSPORT_BUFFER_SIZE  1600
#endif

#define MAX_PAYLOAD_SIZE  (MAX_TRANSPORT_BUFFER_SIZE - H_ESP_PAYLOAD_HEADER_OFFSET)

/* Forward declarations */

struct serial_drv_handle_t;
struct timer_handle_t;
extern struct mempool *nw_mp_g;

/* ESP-Hosted event base */

#include "esp_event_base.h"
ESP_EVENT_DECLARE_BASE(ESP_HOSTED_EVENT);

/* Power save types */

#define HOSTED_POWER_SAVE_TYPE_NONE        0
#define HOSTED_POWER_SAVE_TYPE_DEEP_SLEEP  1
#define HOSTED_POWER_SAVE_TYPE_LIGHT_SLEEP 2

/* Wakeup reasons */

#define HOSTED_WAKEUP_NORMAL_REBOOT  0
#define HOSTED_WAKEUP_DEEP_SLEEP     1
#define HOSTED_WAKEUP_UNDEFINED      2

#endif /* __PORT_ESP_HOSTED_HOST_OS_H */

/*
 * SPDX-FileCopyrightText: 2025-2026 Espressif Systems (Shanghai) CO LTD
 *
 * SPDX-License-Identifier: Apache-2.0
 */

/* NuttX OS abstraction layer implementation for esp_hosted */

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
#include <string.h>
#include <stdlib.h>
#include <syslog.h>
#include <errno.h>

#include <nuttx/mutex.h>
#include <nuttx/semaphore.h>
#include <nuttx/kthread.h>
#include <nuttx/clock.h>
#include <nuttx/arch.h>
#include <nuttx/kmalloc.h>

#include "port_esp_hosted_host_os.h"
#include "port_esp_hosted_host_config.h"
#include "esp_hosted_os_abstraction.h"
#include "esp_event_base.h"

#if H_TRANSPORT_IN_USE == H_TRANSPORT_SDIO
#  include "port_esp_hosted_host_sdio.h"
#endif

/****************************************************************************
 * Private Types
 ****************************************************************************/

/* Internal handle wrappers */

struct nuttx_mutex_s
{
  mutex_t mutex;
};

struct nuttx_sem_s
{
  sem_t sem;
};

struct nuttx_queue_s
{
  sem_t sem;             /* Counting semaphore for items */
  mutex_t lock;          /* Protect queue operations */
  uint8_t *buffer;       /* Ring buffer */
  uint32_t item_size;    /* Size of each item */
  uint32_t max_items;    /* Maximum number of items */
  uint32_t head;         /* Head index */
  uint32_t tail;         /* Tail index */
  uint32_t count;        /* Current item count */
};

struct nuttx_thread_s
{
  int pid;               /* NuttX task PID */
};

struct nuttx_timer_s
{
  struct work_s work;
  int duration_ms;
  int type;              /* 0=oneshot, 1=periodic */
  void (*callback)(void *);
  void *arg;
  bool active;
};

/****************************************************************************
 * Private Data
 ****************************************************************************/

struct mempool *nw_mp_g = NULL;

/* Global hosted config */

ESP_EVENT_DEFINE_BASE(ESP_HOSTED_EVENT);

struct hosted_config_t g_h = HOSTED_CONFIG_INIT_DEFAULT();

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Memory Functions
 ****************************************************************************/

static void *hosted_memcpy(void *dest, const void *src, uint32_t size)
{
  if (size && (!dest || !src))
    {
      return NULL;
    }

  return memcpy(dest, src, size);
}

static void *hosted_memset(void *buf, int val, size_t len)
{
  return memset(buf, val, len);
}

static void *hosted_malloc(size_t size)
{
  return kmm_malloc(size);
}

static void *hosted_calloc(size_t blk_no, size_t size)
{
  void *ptr = kmm_malloc(blk_no * size);
  if (ptr)
    {
      memset(ptr, 0, blk_no * size);
    }

  return ptr;
}

static void hosted_free(void *ptr)
{
  if (ptr)
    {
      kmm_free(ptr);
    }
}

static void *hosted_realloc(void *mem, size_t newsize)
{
  if (newsize == 0)
    {
      hosted_free(mem);
      return NULL;
    }

  return kmm_realloc(mem, newsize);
}

static void *hosted_malloc_align(size_t size, size_t align)
{
  /* For NuttX, use aligned_alloc from kernel heap */

  return kmm_memalign(align, size);
}

static void hosted_free_align(void *ptr)
{
  hosted_free(ptr);
}

/****************************************************************************
 * Thread Functions
 ****************************************************************************/

static void *hosted_thread_create(const char *tname, uint32_t tprio,
                                  uint32_t tstack_size,
                                  void (*start_routine)(void const *),
                                  void *sr_arg)
{
  struct nuttx_thread_s *thread;
  int pid;

  if (!start_routine)
    {
      return NULL;
    }

  thread = (struct nuttx_thread_s *)hosted_malloc(sizeof(*thread));
  if (!thread)
    {
      return NULL;
    }

  pid = kthread_create(tname, tprio, tstack_size,
                       (main_t)start_routine, (char *const *)&sr_arg);
  if (pid < 0)
    {
      hosted_free(thread);
      return NULL;
    }

  thread->pid = pid;
  return thread;
}

static int hosted_thread_cancel(void *thread_handle)
{
  struct nuttx_thread_s *thread;

  if (!thread_handle)
    {
      return RET_INVALID;
    }

  thread = (struct nuttx_thread_s *)thread_handle;

  /* NuttX doesn't have a direct kthread_cancel, but we can signal it */

  hosted_free(thread_handle);
  return RET_OK;
}

static void hosted_thread_yield(void)
{
  sched_yield();
}

/****************************************************************************
 * Sleep Functions
 ****************************************************************************/

static unsigned int hosted_msleep(unsigned int mseconds)
{
  usleep(mseconds * 1000);
  return 0;
}

static unsigned int hosted_usleep(unsigned int useconds)
{
  usleep(useconds);
  return 0;
}

static unsigned int hosted_sleep(unsigned int seconds)
{
  usleep(seconds * 1000000);
  return 0;
}

static unsigned int hosted_for_loop_delay(unsigned int number)
{
  volatile int idx;
  for (idx = 0; idx < 100 * number; idx++)
    {
    }

  return 0;
}

/****************************************************************************
 * Queue Functions (implemented with ring buffer + semaphore)
 ****************************************************************************/

static void *hosted_create_queue(uint32_t qnum_elem, uint32_t qitem_size)
{
  struct nuttx_queue_s *q;

  q = (struct nuttx_queue_s *)hosted_malloc(sizeof(*q));
  if (!q)
    {
      return NULL;
    }

  q->buffer = (uint8_t *)hosted_malloc(qnum_elem * qitem_size);
  if (!q->buffer)
    {
      hosted_free(q);
      return NULL;
    }

  nxmutex_init(&q->lock);
  nxsem_init(&q->sem, 0, 0);
  q->item_size = qitem_size;
  q->max_items = qnum_elem;
  q->head = 0;
  q->tail = 0;
  q->count = 0;

  return q;
}

static int hosted_queue_item(void *queue_handle, void *item, int timeout)
{
  struct nuttx_queue_s *q;
  int ret;

  if (!queue_handle)
    {
      return RET_INVALID;
    }

  q = (struct nuttx_queue_s *)queue_handle;

  ret = nxmutex_lock(&q->lock);
  if (ret < 0)
    {
      return RET_FAIL;
    }

  if (q->count >= q->max_items)
    {
      nxmutex_unlock(&q->lock);
      return RET_FAIL;
    }

  memcpy(q->buffer + q->tail * q->item_size, item, q->item_size);
  q->tail = (q->tail + 1) % q->max_items;
  q->count++;

  nxmutex_unlock(&q->lock);
  nxsem_post(&q->sem);

  return RET_OK;
}

static int hosted_dequeue_item(void *queue_handle, void *item, int timeout)
{
  struct nuttx_queue_s *q;
  int ret;

  if (!queue_handle)
    {
      return RET_INVALID;
    }

  q = (struct nuttx_queue_s *)queue_handle;

  if (timeout == 0)
    {
      ret = nxsem_trywait(&q->sem);
    }
  else if (timeout < 0)
    {
      ret = nxsem_wait(&q->sem);
    }
  else
    {
      struct timespec ts;
      clock_gettime(CLOCK_REALTIME, &ts);
      ts.tv_sec += timeout / 1000;
      ts.tv_nsec += (timeout % 1000) * 1000000;
      if (ts.tv_nsec >= 1000000000)
        {
          ts.tv_sec++;
          ts.tv_nsec -= 1000000000;
        }

      ret = nxsem_timedwait(&q->sem, &ts);
    }

  if (ret < 0)
    {
      return RET_FAIL_TIMEOUT;
    }

  nxmutex_lock(&q->lock);

  memcpy(item, q->buffer + q->head * q->item_size, q->item_size);
  q->head = (q->head + 1) % q->max_items;
  q->count--;

  nxmutex_unlock(&q->lock);

  return RET_OK;
}

static int hosted_queue_msg_waiting(void *queue_handle)
{
  struct nuttx_queue_s *q;

  if (!queue_handle)
    {
      return RET_INVALID;
    }

  q = (struct nuttx_queue_s *)queue_handle;
  return q->count;
}

static int hosted_destroy_queue(void *queue_handle)
{
  struct nuttx_queue_s *q;

  if (!queue_handle)
    {
      return RET_INVALID;
    }

  q = (struct nuttx_queue_s *)queue_handle;

  nxsem_destroy(&q->sem);
  nxmutex_destroy(&q->lock);
  hosted_free(q->buffer);
  hosted_free(q);

  return RET_OK;
}

static int hosted_reset_queue(void *queue_handle)
{
  struct nuttx_queue_s *q;

  if (!queue_handle)
    {
      return RET_INVALID;
    }

  q = (struct nuttx_queue_s *)queue_handle;

  nxmutex_lock(&q->lock);
  q->head = 0;
  q->tail = 0;
  q->count = 0;
  nxmutex_unlock(&q->lock);

  /* Reset semaphore */

  while (nxsem_trywait(&q->sem) == 0)
    {
    }

  return RET_OK;
}

