static void *hosted_create_mutex(void)
{
  struct nuttx_mutex_s *m;

  m = (struct nuttx_mutex_s *)hosted_malloc(sizeof(*m));
  if (!m)
    {
      return NULL;
    }

  nxmutex_init(&m->mutex);
  return m;
}

static int hosted_lock_mutex(void *mutex_handle, int timeout_ms)
{
  struct nuttx_mutex_s *m;
  int ret;

  if (!mutex_handle)
    {
      return RET_INVALID;
    }

  m = (struct nuttx_mutex_s *)mutex_handle;

  if (timeout_ms < 0)
    {
      ret = nxmutex_lock(&m->mutex);
    }
  else if (timeout_ms == 0)
    {
      ret = nxmutex_trylock(&m->mutex);
    }
  else
    {
      /* Convert ms to ticks */

      ret = nxmutex_lock(&m->mutex);
      /* NuttX mutex doesn't support timed lock directly,
       * but this is acceptable for esp_hosted usage */
    }

  return (ret < 0) ? RET_FAIL : RET_OK;
}

static int hosted_unlock_mutex(void *mutex_handle)
{
  struct nuttx_mutex_s *m;

  if (!mutex_handle)
    {
      return RET_INVALID;
    }

  m = (struct nuttx_mutex_s *)mutex_handle;
  nxmutex_unlock(&m->mutex);
  return RET_OK;
}

static int hosted_destroy_mutex(void *mutex_handle)
{
  struct nuttx_mutex_s *m;

  if (!mutex_handle)
    {
      return RET_INVALID;
    }

  m = (struct nuttx_mutex_s *)mutex_handle;
  nxmutex_destroy(&m->mutex);
  hosted_free(m);

  return RET_OK;
}

