/****************************************************************************
 * Timer Functions (using NuttX work queue)
 ****************************************************************************/

static void timer_work_handler(FAR void *arg)
{
  struct nuttx_timer_s *timer = (struct nuttx_timer_s *)arg;

  if (timer && timer->active && timer->callback)
    {
      timer->callback(timer->arg);

      /* Re-schedule if periodic */

      if (timer->type == 1 && timer->active)
        {
          work_queue(LPWORK, &timer->work, timer_work_handler,
                     timer, MSEC2TICK(timer->duration_ms));
        }
    }
}

static void *hosted_timer_start(const char *name, int duration_ms, int type,
                                void (*timeout_handler)(void *), void *arg)
{
  struct nuttx_timer_s *timer;

  if (!timeout_handler)
    {
      return NULL;
    }

  timer = (struct nuttx_timer_s *)hosted_malloc(sizeof(*timer));
  if (!timer)
    {
      return NULL;
    }

  timer->duration_ms = duration_ms;
  timer->type = type;
  timer->callback = timeout_handler;
  timer->arg = arg;
  timer->active = true;

  work_queue(LPWORK, &timer->work, timer_work_handler,
             timer, MSEC2TICK(duration_ms));

  return timer;
}

static int hosted_timer_stop(void *timer_handle)
{
  struct nuttx_timer_s *timer;

  if (!timer_handle)
    {
      return RET_FAIL;
    }

  timer = (struct nuttx_timer_s *)timer_handle;
  timer->active = false;
  work_cancel(LPWORK, &timer->work);
  hosted_free(timer);

  return RET_OK;
}

static uint64_t hosted_get_time_ms(void)
{
  struct timespec ts;
  clock_gettime(CLOCK_MONOTONIC, &ts);
  return (uint64_t)ts.tv_sec * 1000 + ts.tv_nsec / 1000000;
}

