#define FUNC1_EN_MASK         (BIT(1))
#define SDIO_INIT_MAX_RETRY   10

#define SDIO_FAIL_IF_NULL(x) \
  do { \
    if (!(x)) return ESP_FAIL; \
  } while (0)

#define SDIO_LOCK(x) \
  do { \
    if (x) g_h.funcs->_h_lock_mutex(sdio_bus_lock, HOSTED_BLOCK_MAX); \
  } while (0)

#define SDIO_UNLOCK(x) \
  do { \
    if (x) g_h.funcs->_h_unlock_mutex(sdio_bus_lock); \
  } while (0)

