/****************************************************************************
 * Name: hosted_sdio_set_blocksize
 ****************************************************************************/

static esp_err_t hosted_sdio_set_blocksize(sdmmc_card_t *card, uint8_t fn,
                                           uint16_t value)
{
  size_t offset = SD_IO_FBR_START * fn;
  const uint8_t *bs_u8 = (const uint8_t *)&value;
  uint16_t bs_read = 0;
  uint8_t *bs_read_u8 = (uint8_t *)&bs_read;

  sdmmc_io_write_byte(card, SDIO_FUNC_0,
                      offset + SD_IO_CCCR_BLKSIZEL, bs_u8[0], NULL);
  sdmmc_io_write_byte(card, SDIO_FUNC_0,
                      offset + SD_IO_CCCR_BLKSIZEH, bs_u8[1], NULL);
  sdmmc_io_read_byte(card, SDIO_FUNC_0,
                     offset + SD_IO_CCCR_BLKSIZEL, &bs_read_u8[0]);
  sdmmc_io_read_byte(card, SDIO_FUNC_0,
                     offset + SD_IO_CCCR_BLKSIZEH, &bs_read_u8[1]);

  syslog(LOG_INFO, TAG ": Function %d Blocksize: %d\n", fn, bs_read);

  return (bs_read == value) ? ESP_OK : ESP_FAIL;
}

/****************************************************************************
 * Name: hosted_sdio_card_fn_init
 ****************************************************************************/

static esp_err_t hosted_sdio_card_fn_init(sdmmc_card_t *card)
{
  uint8_t ioe = 0;
  uint8_t ior = 0;
  uint8_t ie = 0;
  uint8_t bus_width = 0;
  uint16_t bs = 0;
  int i = 0;

  SDIO_FAIL_IF_NULL(card);

  /* Read IO Enable register */

  if (ESP_OK != sdmmc_io_read_byte(card, SDIO_FUNC_0,
                                   SD_IO_CCCR_FN_ENABLE, &ioe))
    {
      return ESP_FAIL;
    }

  syslog(LOG_DEBUG, TAG ": IOE: 0x%02x\n", ioe);

  /* Read IO Ready register */

  if (ESP_OK != sdmmc_io_read_byte(card, SDIO_FUNC_0,
                                   SD_IO_CCCR_FN_READY, &ior))
    {
      return ESP_FAIL;
    }

  syslog(LOG_DEBUG, TAG ": IOR: 0x%02x\n", ior);

  /* Enable function 1 */

  ioe |= FUNC1_EN_MASK;
  if (ESP_OK != sdmmc_io_write_byte(card, SDIO_FUNC_0,
                                    SD_IO_CCCR_FN_ENABLE, ioe, &ioe))
    {
      return ESP_FAIL;
    }

  /* Wait for function 1 to become ready */

  for (i = 0; i < SDIO_INIT_MAX_RETRY; i++)
    {
      if (ESP_OK != sdmmc_io_read_byte(card, SDIO_FUNC_0,
                                       SD_IO_CCCR_FN_READY, &ior))
        {
          return ESP_FAIL;
        }

      if (ior & FUNC1_EN_MASK)
        {
          break;
        }
      else
        {
          usleep(10 * 1000);
        }
    }

  if (i >= SDIO_INIT_MAX_RETRY)
    {
      syslog(LOG_ERR, TAG ": SDIO function 1 not ready\n");
      return ESP_FAIL;
    }

  /* Enable interrupts for function 1 and master enable */

  sdmmc_io_read_byte(card, SDIO_FUNC_0, SD_IO_CCCR_INT_ENABLE, &ie);
  ie |= BIT(0) | FUNC1_EN_MASK;
  sdmmc_io_write_byte(card, SDIO_FUNC_0, SD_IO_CCCR_INT_ENABLE, ie, NULL);
  sdmmc_io_read_byte(card, SDIO_FUNC_0, SD_IO_CCCR_INT_ENABLE, &ie);
  syslog(LOG_DEBUG, TAG ": IE: 0x%02x\n", ie);

  /* Get bus width register */

  sdmmc_io_read_byte(card, SDIO_FUNC_0, SD_IO_CCCR_BUS_WIDTH, &bus_width);
  syslog(LOG_DEBUG, TAG ": BUS_WIDTH: 0x%02x\n", bus_width);

  /* Set FN0 block size to 512 */

  bs = 512;
  hosted_sdio_set_blocksize(card, SDIO_FUNC_0, bs);

  /* Set FN1 block size to 512 */

  bs = 512;
  hosted_sdio_set_blocksize(card, SDIO_FUNC_1, bs);

  return ESP_OK;
}

/****************************************************************************
 * Name: sdio_read_fromio
 ****************************************************************************/

static esp_err_t sdio_read_fromio(sdmmc_card_t *card, uint32_t function,
                                  uint32_t addr, uint8_t *data,
                                  uint16_t size)
{
  uint16_t remainder = size;
  uint16_t blocks;
  esp_err_t res;
  uint8_t *ptr = data;

  /* Do block mode transfer */

  while (remainder >= ESP_BLOCK_SIZE)
    {
      blocks = H_SDIO_RX_BLOCKS_TO_TRANSFER(remainder);
      size = blocks * ESP_BLOCK_SIZE;
      res = sdmmc_io_read_blocks(card, function, addr, ptr, size);
      if (res)
        {
          return res;
        }

      remainder -= size;
      ptr += size;
      addr += size;
    }

  /* Transfer remainder using byte mode */

  while (remainder > 0)
    {
      size = remainder;
      res = sdmmc_io_read_bytes(card, function, addr, ptr, size);
      if (res)
        {
          return res;
        }

      remainder -= size;
      ptr += size;
      addr += size;
    }

  return ESP_OK;
}

/****************************************************************************
 * Name: sdio_write_toio
 ****************************************************************************/

static esp_err_t sdio_write_toio(sdmmc_card_t *card, uint32_t function,
                                 uint32_t addr, uint8_t *data,
                                 uint16_t size)
{
  uint16_t remainder = size;
  uint16_t blocks;
  esp_err_t res;
  uint8_t *ptr = data;

  /* Do block mode transfer */

  while (remainder >= ESP_BLOCK_SIZE)
    {
      blocks = H_SDIO_TX_BLOCKS_TO_TRANSFER(remainder);
      size = blocks * ESP_BLOCK_SIZE;
      res = sdmmc_io_write_blocks(card, function, addr, ptr, size);
      if (res)
        {
          return res;
        }

      remainder -= size;
      ptr += size;
      addr += size;
    }

  /* Transfer remainder using byte mode */

  while (remainder > 0)
    {
      size = remainder;
      res = sdmmc_io_write_bytes(card, function, addr, ptr, size);
      if (res)
        {
          return res;
        }

      remainder -= size;
      ptr += size;
      addr += size;
    }

  return ESP_OK;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: hosted_sdio_init
 ****************************************************************************/

void *hosted_sdio_init(void)
{
  esp_err_t res;

  syslog(LOG_INFO, TAG ": Initializing SDIO host\n");

  /* Guard against multiple initialization */

  if (sdio_bus_lock)
    {
      syslog(LOG_WARNING, TAG ": SDIO already initialized\n");
      return (void *)&context;
    }

  /* Configure SDIO pins from Kconfig */

  context.config.clock_freq_khz = H_SDIO_CLOCK_FREQ_KHZ;
  context.config.bus_width       = H_SDIO_BUS_WIDTH;
  context.config.slot            = H_SDMMC_HOST_SLOT;
  context.config.pin_clk.pin     = H_SDIO_PIN_CLK;
  context.config.pin_cmd.pin     = H_SDIO_PIN_CMD;
  context.config.pin_d0.pin      = H_SDIO_PIN_D0;
  context.config.pin_d1.pin      = H_SDIO_PIN_D1;
  context.config.pin_d2.pin      = H_SDIO_PIN_D2;
  context.config.pin_d3.pin      = H_SDIO_PIN_D3;

  /* Initialize SDMMC host */

  res = sdmmc_host_init();
  if (res != ESP_OK)
    {
      syslog(LOG_ERR, TAG ": Failed to initialize SDMMC host: %d\n", res);
      return NULL;
    }

  /* Configure SDIO slot with GPIO matrix pins */

  sdmmc_slot_config_t slot_config = SDMMC_SLOT_CONFIG_DEFAULT();
  slot_config.width = context.config.bus_width;

#ifdef H_SDIO_SOC_USE_GPIO_MATRIX
  slot_config.clk = context.config.pin_clk.pin;
  slot_config.cmd = context.config.pin_cmd.pin;
  slot_config.d0  = context.config.pin_d0.pin;
  slot_config.d1  = context.config.pin_d1.pin;
  slot_config.d2  = context.config.pin_d2.pin;
  slot_config.d3  = context.config.pin_d3.pin;
#endif

  res = sdmmc_host_init_slot(context.config.slot, &slot_config);
  if (res != ESP_OK)
    {
      syslog(LOG_ERR, TAG ": Failed to init SDMMC slot %d: %d\n",
             H_SDMMC_HOST_SLOT, res);
      return NULL;
    }

  /* Allocate card structure */

  context.card = (sdmmc_card_t *)g_h.funcs->_h_malloc(sizeof(sdmmc_card_t));
  if (!context.card)
    {
      syslog(LOG_ERR, TAG ": Failed to allocate card structure\n");
      return NULL;
    }

  /* Initialize bus lock mutex */

  sdio_bus_lock = g_h.funcs->_h_create_mutex();
  if (!sdio_bus_lock)
    {
      syslog(LOG_ERR, TAG ": Failed to create bus lock\n");
      g_h.funcs->_h_free(context.card);
      context.card = NULL;
      return NULL;
    }

  syslog(LOG_INFO, TAG ": SDIO host initialized\n");
  return (void *)&context;
}

/****************************************************************************
 * Name: hosted_sdio_deinit
 ****************************************************************************/

int hosted_sdio_deinit(void *ctx)
{
  SDIO_FAIL_IF_NULL(ctx);

  sdmmc_context_t *sdio_ctx = (sdmmc_context_t *)ctx;

  if (sdio_ctx->card)
    {
      g_h.funcs->_h_free(sdio_ctx->card);
      sdio_ctx->card = NULL;
    }

  if (sdio_bus_lock)
    {
      g_h.funcs->_h_destroy_mutex(sdio_bus_lock);
      sdio_bus_lock = NULL;
    }

  sdmmc_host_deinit();
  return ESP_OK;
}

/****************************************************************************
 * Name: hosted_sdio_card_init
 ****************************************************************************/

int hosted_sdio_card_init(void *ctx, bool show_config)
{
  SDIO_FAIL_IF_NULL(ctx);

  sdmmc_context_t *sdio_ctx = (sdmmc_context_t *)ctx;
  struct esp_hosted_sdio_config *sdio_config = &sdio_ctx->config;

  SDIO_FAIL_IF_NULL(sdio_config);
  SDIO_FAIL_IF_NULL(sdio_ctx->card);

  sdmmc_host_t config = SDMMC_HOST_DEFAULT();
  config.slot = sdio_config->slot;
  config.max_freq_khz = sdio_config->clock_freq_khz;

  /* Set aligned buffer flag for ESP32-P4 DMA requirements */

#ifdef CONFIG_IDF_TARGET_ESP32P4
  config.flags |= SDMMC_HOST_FLAG_ALLOC_ALIGNED_BUF;
#endif

  if (show_config)
    {
      syslog(LOG_INFO, TAG ": SDIO Slot %d, %d-bit, %u KHz\n",
             config.slot, sdio_config->bus_width == 4 ? 4 : 1,
             config.max_freq_khz);
      syslog(LOG_INFO, TAG ": CLK=%d CMD=%d D0=%d D1=%d D2=%d D3=%d\n",
             sdio_config->pin_clk.pin, sdio_config->pin_cmd.pin,
             sdio_config->pin_d0.pin, sdio_config->pin_d1.pin,
             sdio_config->pin_d2.pin, sdio_config->pin_d3.pin);
    }

  /* Initialize the SDIO card */

  if (sdmmc_card_init(&config, sdio_ctx->card) != ESP_OK)
    {
      syslog(LOG_ERR, TAG ": sdmmc_card_init failed\n");
      return ESP_FAIL;
    }

  /* Initialize card functions (enable FN1, set block size, etc.) */

  if (hosted_sdio_card_fn_init(sdio_ctx->card) != ESP_OK)
    {
      syslog(LOG_ERR, TAG ": sdio_card_fn_init failed\n");
      return ESP_FAIL;
    }

  syslog(LOG_INFO, TAG ": SDIO card initialized\n");
  return ESP_OK;
}

/****************************************************************************
 * Name: hosted_sdio_card_deinit
 ****************************************************************************/

int hosted_sdio_card_deinit(void *ctx)
{
  SDIO_FAIL_IF_NULL(ctx);

  sdmmc_context_t *sdio_ctx = (sdmmc_context_t *)ctx;

  /* Free DMA aligned buffer if allocated */

  if (sdio_ctx->card && sdio_ctx->card->host.dma_aligned_buffer)
    {
      free(sdio_ctx->card->host.dma_aligned_buffer);
      sdio_ctx->card->host.dma_aligned_buffer = NULL;
    }

  return ESP_OK;
}

/****************************************************************************
 * Name: hosted_sdio_read_reg
 ****************************************************************************/

int hosted_sdio_read_reg(void *ctx, uint32_t reg, uint8_t *data,
                         uint16_t size, bool lock_required)
{
  int res = 0;

  SDIO_FAIL_IF_NULL(ctx);

  sdmmc_context_t *sdio_ctx = (sdmmc_context_t *)ctx;
  sdmmc_card_t *card = sdio_ctx->card;
  SDIO_FAIL_IF_NULL(card);

  /* Apply address mask for slave registers */

  reg &= ESP_ADDRESS_MASK;

  SDIO_LOCK(lock_required);
  if (size <= 1)
    {
      res = sdmmc_io_read_byte(card, SDIO_FUNC_1, reg, data);
    }
  else
    {
      res = sdmmc_io_read_bytes(card, SDIO_FUNC_1, reg, data, size);
    }

  SDIO_UNLOCK(lock_required);
  return res;
}

/****************************************************************************
 * Name: hosted_sdio_write_reg
 ****************************************************************************/

int hosted_sdio_write_reg(void *ctx, uint32_t reg, uint8_t *data,
                          uint16_t size, bool lock_required)
{
  int res = 0;

  SDIO_FAIL_IF_NULL(ctx);

  sdmmc_context_t *sdio_ctx = (sdmmc_context_t *)ctx;
  sdmmc_card_t *card = sdio_ctx->card;

  /* Apply address mask for slave registers */

  reg &= ESP_ADDRESS_MASK;

  SDIO_LOCK(lock_required);
  if (size <= 1)
    {
      res = sdmmc_io_write_byte(card, SDIO_FUNC_1, reg, *data, NULL);
    }
  else
    {
      res = sdmmc_io_write_bytes(card, SDIO_FUNC_1, reg, data, size);
    }

  SDIO_UNLOCK(lock_required);
  return res;
}

/****************************************************************************
 * Name: hosted_sdio_read_block
 ****************************************************************************/

int hosted_sdio_read_block(void *ctx, uint32_t reg, uint8_t *data,
                           uint16_t size, bool lock_required)
{
  int res = 0;

  SDIO_FAIL_IF_NULL(ctx);

  sdmmc_context_t *sdio_ctx = (sdmmc_context_t *)ctx;
  sdmmc_card_t *card = sdio_ctx->card;
