/* NuttX WiFi network device driver for esp_hosted
 *
 * This driver bridges the esp_hosted library to the NuttX network stack.
 * It registers as a NET_LL_IEEE80211 device (wlan0) and implements
 * wireless extension ioctls for wapi compatibility.
 */

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/arch.h>
#include <nuttx/net/netdev.h>
#include <nuttx/net/ip.h>
#include <nuttx/wqueue.h>
#include <nuttx/clock.h>
#include <nuttx/mutex.h>
#include <nuttx/wireless/wireless.h>
#include <debug.h>
#include <errno.h>
#include <string.h>
#include <syslog.h>
#include <stdio.h>

#include <net/if.h>
#include <arpa/inet.h>

#ifdef CONFIG_NET_IPv4
#  include <nuttx/net/arp.h>
#endif

#include "esp_hosted_wifi.h"
#include "esp_hosted.h"

/* esp_hosted WiFi API */

#include "esp_wifi.h"
#include "esp_wifi_types.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define WIFI_TAG  "esp_wifi"
#define WIFI_ERR(...)   syslog(LOG_ERR, WIFI_TAG ": " __VA_ARGS__)
#define WIFI_INFO(...)  syslog(LOG_INFO, WIFI_TAG ": " __VA_ARGS__)
#define WIFI_DBG(...)   syslog(LOG_DEBUG, WIFI_TAG ": " __VA_ARGS__)

/* Work queue timing */

#define WIFI_POLL_INTERVAL    MSEC2TICK(50)

/* Maximum scan results */

#define MAX_SCAN_RESULTS      16
#define MAX_SSID_LEN          32
#define MAX_PASSWORD_LEN      64

/* WiFi status */

#define WIFI_STATUS_DISCONNECTED  0
#define WIFI_STATUS_CONNECTED     1

/****************************************************************************
 * Private Types
 ****************************************************************************/

/* WiFi driver private data */

struct esp_wifi_dev_s
{
  struct net_driver_s  netdev;         /* NuttX network device */
  struct work_s        pollwork;       /* Deferred poll work */
  bool                 ifup;           /* Interface is up */
  bool                 connected;      /* WiFi connected */
  bool                 initialized;    /* esp_hosted initialized */
  uint8_t              mac[6];         /* MAC address */
  uint8_t              rxbuf[1600];    /* Receive buffer */
  char                 ssid[MAX_SSID_LEN + 1];     /* Current SSID */
  char                 password[MAX_PASSWORD_LEN];  /* Current password */
  uint8_t              status;         /* WiFi status */
  mutex_t              lock;           /* Thread safety */
  wifi_scan_result_t   scan_results[MAX_SCAN_RESULTS];
  int                  scan_count;
};

/****************************************************************************
 * Private Function Prototypes
 ****************************************************************************/

static int  esp_wifi_ifup(FAR struct net_driver_s *dev);
static int  esp_wifi_ifdown(FAR struct net_driver_s *dev);
static int  esp_wifi_transmit(FAR struct net_driver_s *dev);
static int  esp_wifi_txavail(FAR struct net_driver_s *dev);
#ifdef CONFIG_NET_MCASTGROUP
static int  esp_wifi_addmac(FAR struct net_driver_s *dev,
                            FAR const uint8_t *mac);
static int  esp_wifi_rmmac(FAR struct net_driver_s *dev,
                           FAR const uint8_t *mac);
#endif
#ifdef CONFIG_NETDEV_IOCTL
static int  esp_wifi_ioctl(FAR struct net_driver_s *dev, int cmd,
                           unsigned long arg);
#endif
static void esp_wifi_poll_work(FAR void *arg);

/****************************************************************************
 * Private Data
 ****************************************************************************/

static struct esp_wifi_dev_s g_wifi;

/****************************************************************************
 * Private Functions - WiFi Operations
 ****************************************************************************/

/****************************************************************************
 * Name: esp_wifi_do_connect
 ****************************************************************************/

static int esp_wifi_do_connect(const char *ssid, const char *password)
{
  wifi_config_t wifi_config;
  esp_err_t err;

  memset(&wifi_config, 0, sizeof(wifi_config));
  strncpy((char *)wifi_config.sta.ssid, ssid,
          sizeof(wifi_config.sta.ssid) - 1);
  strncpy((char *)wifi_config.sta.password, password,
          sizeof(wifi_config.sta.password) - 1);

  err = esp_wifi_set_mode(WIFI_MODE_STA);
  if (err != ESP_OK)
    {
      WIFI_ERR("Failed to set STA mode: %d\n", err);
      return -EIO;
    }

  err = esp_wifi_set_config(WIFI_IF_STA, &wifi_config);
  if (err != ESP_OK)
    {
      WIFI_ERR("Failed to set config: %d\n", err);
      return -EIO;
    }

  err = esp_wifi_connect();
  if (err != ESP_OK)
    {
      WIFI_ERR("Failed to connect: %d\n", err);
      return -EIO;
    }

  WIFI_INFO("Connecting to '%s'\n", ssid);
  strncpy(g_wifi.ssid, ssid, MAX_SSID_LEN);
  strncpy(g_wifi.password, password, MAX_PASSWORD_LEN - 1);

  return OK;
}

/****************************************************************************
 * Name: esp_wifi_do_disconnect
 ****************************************************************************/

static int esp_wifi_do_disconnect(void)
{
  esp_err_t err;

  err = esp_wifi_disconnect();
  if (err != ESP_OK)
    {
      WIFI_ERR("Failed to disconnect: %d\n", err);
      return -EIO;
    }

  g_wifi.connected = false;
  g_wifi.status = WIFI_STATUS_DISCONNECTED;
  memset(g_wifi.ssid, 0, sizeof(g_wifi.ssid));
  netdev_carrier_off(&g_wifi.netdev);

  WIFI_INFO("Disconnected\n");
  return OK;
}

/****************************************************************************
 * Name: esp_wifi_do_scan
 ****************************************************************************/

static int esp_wifi_do_scan(void)
{
  wifi_scan_config_t scan_config;
  esp_err_t err;

  memset(&scan_config, 0, sizeof(scan_config));
  scan_config.show_hidden = true;

  err = esp_wifi_scan_start(&scan_config, true);
  if (err != ESP_OK)
    {
      WIFI_ERR("Scan failed: %d\n", err);
      return -EIO;
    }

  /* Get scan results */

  uint16_t count = MAX_SCAN_RESULTS;
  err = esp_wifi_scan_get_ap_records(&count,
                                     (wifi_ap_record_t *)g_wifi.scan_results);
  if (err != ESP_OK)
    {
      WIFI_ERR("Get scan results failed: %d\n", err);
      return -EIO;
    }

  g_wifi.scan_count = count;
  WIFI_INFO("Scan complete, %d results\n", count);
  return OK;
}

/****************************************************************************
 * Private Functions - Network Device Callbacks
 ****************************************************************************/

/****************************************************************************
 * Name: esp_wifi_ifup
 ****************************************************************************/

static int esp_wifi_ifup(FAR struct net_driver_s *dev)
{
  FAR struct esp_wifi_dev_s *priv =
    (FAR struct esp_wifi_dev_s *)dev->d_private;

  WIFI_INFO("Bringing up WiFi interface\n");

  priv->ifup = true;

  /* Initialize esp_hosted if not done yet */

  if (!priv->initialized)
    {
      esp_err_t err;

      err = esp_hosted_init();
      if (err != ESP_OK)
        {
          WIFI_ERR("esp_hosted_init failed: %d\n", err);
          return -EIO;
        }

      err = esp_wifi_init(WIFI_INIT_CONFIG_DEFAULT());
      if (err != ESP_OK)
        {
          WIFI_ERR("esp_wifi_init failed: %d\n", err);
          return -EIO;
        }

      err = esp_wifi_start();
      if (err != ESP_OK)
        {
          WIFI_ERR("esp_wifi_start failed: %d\n", err);
          return -EIO;
        }

      priv->initialized = true;
      WIFI_INFO("esp_hosted initialized\n");
    }

  /* Start periodic poll work */

  work_queue(LPWORK, &priv->pollwork, esp_wifi_poll_work,
             priv, WIFI_POLL_INTERVAL);

  return OK;
}

/****************************************************************************
 * Name: esp_wifi_ifdown
 ****************************************************************************/

static int esp_wifi_ifdown(FAR struct net_driver_s *dev)
{
  FAR struct esp_wifi_dev_s *priv =
    (FAR struct esp_wifi_dev_s *)dev->d_private;

  WIFI_INFO("Bringing down WiFi interface\n");

  work_cancel(LPWORK, &priv->pollwork);

  if (priv->connected)
    {
      esp_wifi_do_disconnect();
    }

  priv->ifup = false;
  return OK;
}

/****************************************************************************
 * Name: esp_wifi_transmit
 ****************************************************************************/

static int esp_wifi_transmit(FAR struct net_driver_s *dev)
{
  /* The esp_hosted library handles TX internally through the WiFi API.
   * The NuttX network stack calls d_txavail when there's data to send,
   * but for esp_hosted, the actual TX is handled by the WiFi driver
   * on the ESP32-C6 side. We just need to signal that we're ready.
   */

  return OK;
}

