/****************************************************************************
 * Name: esp_wifi_ioctl
 ****************************************************************************/

#ifdef CONFIG_NETDEV_IOCTL
static int esp_wifi_ioctl(FAR struct net_driver_s *dev, int cmd,
                          unsigned long arg)
{
  FAR struct esp_wifi_dev_s *priv =
    (FAR struct esp_wifi_dev_s *)dev->d_private;
  int ret = -ENOTTY;

  switch (cmd)
    {
      /* SIOCSIWESSID - Set ESSID (connect to AP) */

      case SIOCSIWESSID:
        {
          struct iwreq *iwr = (struct iwreq *)arg;
          if (iwr && iwr->u.essid.pointer)
            {
              char ssid[MAX_SSID_LEN + 1];
              int len = iwr->u.essid.length;
              if (len > MAX_SSID_LEN)
                {
                  len = MAX_SSID_LEN;
                }

              memset(ssid, 0, sizeof(ssid));
              memcpy(ssid, iwr->u.essid.pointer, len);

              ret = esp_wifi_do_connect(ssid, priv->password);
            }
        }
        break;

      /* SIOCGIWESSID - Get ESSID */

      case SIOCGIWESSID:
        {
          struct iwreq *iwr = (struct iwreq *)arg;
          if (iwr && iwr->u.essid.pointer)
            {
              strncpy(iwr->u.essid.pointer, priv->ssid,
                      iwr->u.essid.length - 1);
              iwr->u.essid.length = strlen(priv->ssid);
              ret = OK;
            }
        }
        break;

      /* SIOCSIWSCAN - Initiate scan */

      case SIOCSIWSCAN:
        ret = esp_wifi_do_scan();
        break;

      /* SIOCGIWSCAN - Get scan results */

      case SIOCGIWSCAN:
        ret = priv->scan_count;
        break;

      /* SIOCSIWENCODEEXT - Set encryption key */

      case SIOCSIWENCODEEXT:
        {
          struct iwreq *iwr = (struct iwreq *)arg;
          if (iwr && iwr->u.encoding.pointer)
            {
              int len = iwr->u.encoding.length;
              if (len > MAX_PASSWORD_LEN - 1)
                {
                  len = MAX_PASSWORD_LEN - 1;
                }

              memset(priv->password, 0, sizeof(priv->password));
              memcpy(priv->password, iwr->u.encoding.pointer, len);
              ret = OK;
            }
        }
        break;

      /* SIOCSIWAUTH - Set auth parameters */

      case SIOCSIWAUTH:
        ret = OK;
        break;

      /* SIOCSIWGENIE - Set generic IE */

      case SIOCSIWGENIE:
        ret = OK;
        break;

      /* SIOCSIWPMKSA - PMKSA cache operation */

      case SIOCSIWPMKSA:
        ret = OK;
        break;

      /* SIOCSIWMODE - Set operating mode */

      case SIOCSIWMODE:
        ret = OK;
        break;

      /* SIOCGIWMODE - Get operating mode */

      case SIOCGIWMODE:
        {
          int *mode = (int *)arg;
          if (mode)
            {
              *mode = IW_MODE_INFRA;
              ret = OK;
            }
        }
        break;

      /* SIOCSIWFREQ - Set channel/frequency */

      case SIOCSIWFREQ:
        ret = OK;
        break;

      /* SIOCGIWFREQ - Get channel/frequency */

      case SIOCGIWFREQ:
        ret = OK;
        break;

      /* SIOCSIWRATE - Set bitrate */

      case SIOCSIWRATE:
        ret = OK;
        break;

      /* SIOCGIWRATE - Get bitrate */

      case SIOCGIWRATE:
        ret = OK;
        break;

      /* SIOCSIWRTS - Set RTS threshold */

      case SIOCSIWRTS:
        ret = OK;
        break;

      /* SIOCSIWFRAG - Set fragmentation threshold */

      case SIOCSIWFRAG:
        ret = OK;
        break;

      /* SIOCSIWTXPOW - Set transmit power */

      case SIOCSIWTXPOW:
        ret = OK;
        break;

      /* SIOCSIWRETRY - Set retry limits */

      case SIOCSIWRETRY:
        ret = OK;
        break;

      /* SIOCSIWPOWER - Set power management */

      case SIOCSIWPOWER:
        ret = OK;
        break;

      default:
        WIFI_DBG("Unknown ioctl 0x%x\n", cmd);
        break;
    }

  return ret;
}
#endif /* CONFIG_NETDEV_IOCTL */

/****************************************************************************
 * Name: esp_wifi_poll_work
 *
 * Description:
 *   Periodic work to check for incoming packets from esp_hosted.
 *   For esp_hosted, the RX path is handled through the WiFi API
 *   callbacks. This poll work handles the carrier detection.
 *
 ****************************************************************************/

static void esp_wifi_poll_work(FAR void *arg)
{
  FAR struct esp_wifi_dev_s *priv = (FAR struct esp_wifi_dev_s *)arg;

  if (!priv->ifup)
    {
      return;
    }

  /* Check WiFi connection status */

  wifi_ap_record_t ap_info;
  esp_err_t err = esp_wifi_sta_get_ap_info(&ap_info);

  if (err == ESP_OK && !priv->connected)
    {
      /* Just connected */

      priv->connected = true;
      priv->status = WIFI_STATUS_CONNECTED;
      netdev_carrier_on(&priv->netdev);
      WIFI_INFO("Connected to '%s'\n", ap_info.ssid);
    }
  else if (err != ESP_OK && priv->connected)
    {
      /* Disconnected */

      priv->connected = false;
      priv->status = WIFI_STATUS_DISCONNECTED;
      netdev_carrier_off(&priv->netdev);
      WIFI_INFO("Connection lost\n");
    }

  /* Re-schedule poll work */

  if (priv->ifup)
    {
      work_queue(LPWORK, &priv->pollwork, esp_wifi_poll_work,
                 priv, WIFI_POLL_INTERVAL);
    }
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: esp_hosted_wifi_init
 *
 * Description:
 *   Initialize the esp_hosted WiFi driver and register as wlan0.
 *
 ****************************************************************************/

int esp_hosted_wifi_init(void)
{
  int ret;

  WIFI_INFO("Initializing esp_hosted WiFi driver\n");

  memset(&g_wifi, 0, sizeof(g_wifi));
  nxmutex_init(&g_wifi.lock);

  /* Set default MAC address (will be updated by esp_hosted) */

  g_wifi.mac[0] = 0x02;
  g_wifi.mac[1] = 0x00;
  g_wifi.mac[2] = 0x00;
  g_wifi.mac[3] = 0x00;
  g_wifi.mac[4] = 0x00;
  g_wifi.mac[5] = 0x01;

  /* Configure network device callbacks */

  g_wifi.netdev.d_ifup    = esp_wifi_ifup;
  g_wifi.netdev.d_ifdown  = esp_wifi_ifdown;
  g_wifi.netdev.d_txavail = esp_wifi_txavail;
#ifdef CONFIG_NETDEV_IOCTL
  g_wifi.netdev.d_ioctl   = esp_wifi_ioctl;
#endif
#ifdef CONFIG_NET_MCASTGROUP
  g_wifi.netdev.d_addmac  = esp_wifi_addmac;
  g_wifi.netdev.d_rmmac   = esp_wifi_rmmac;
#endif
  g_wifi.netdev.d_private = &g_wifi;

  /* Set MAC address */

  memcpy(g_wifi.netdev.d_mac.ether.ether_addr_octet, g_wifi.mac, 6);

  /* Register network device */

  ret = netdev_register(&g_wifi.netdev, NET_LL_IEEE80211);
  if (ret < 0)
    {
      WIFI_ERR("netdev_register failed: %d\n", ret);
      return ret;
    }

  WIFI_INFO("WiFi driver registered as wlan0\n");
  return OK;
}

