/*
 * SPDX-License-Identifier: Apache-2.0
 *
 * Self-contained esp_hosted WiFi driver for NuttX on ESP32-P4.
 * Uses esp-hal-3rdparty SDMMC HAL for SDIO communication.
 * Implements esp_hosted protocol directly (no ESP-IDF dependency).
 */

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/arch.h>
#include <nuttx/net/netdev.h>
#include <nuttx/net/ip.h>
#include <nuttx/wqueue.h>
#include <nuttx/clock.h>
#include <nuttx/mutex.h>
#include <nuttx/wireless/wireless.h>
#include <nuttx/kmalloc.h>
#include <debug.h>
#include <errno.h>
#include <string.h>
#include <syslog.h>
#include <stdio.h>

#include <net/if.h>
#include <arpa/inet.h>

#ifdef CONFIG_NET_IPv4
#  include <nuttx/net/arp.h>
#endif

#include "esp_hosted_wifi.h"

/* SDMMC HAL from esp-hal-3rdparty */

#include "driver/sdmmc_host.h"
#include "driver/sdmmc_defs.h"
#include "sdmmc_cmd.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define TAG  "esp_wifi"
#define WIFI_ERR(...)   syslog(LOG_ERR, TAG ": " __VA_ARGS__)
#define WIFI_INFO(...)  syslog(LOG_INFO, TAG ": " __VA_ARGS__)
#define WIFI_DBG(...)   syslog(LOG_DEBUG, TAG ": " __VA_ARGS__)

/* esp_hosted protocol definitions */

#define ESP_STA_IF                  1
#define ESP_AP_IF                   2
#define ESP_PAYLOAD_HEADER_SIZE     12
#define ESP_SLAVE_CMD53_END_ADDR    0x1F800
#define ESP_BLOCK_SIZE              512
#define ESP_RX_BUFFER_SIZE          1536
#define ESP_ADDRESS_MASK            0x3FF

/* SDIO slave register addresses */

#define ESP_SLAVE_SLCHOST_BASE      0x3FF55000
#define ESP_SLAVE_INT_RAW_REG       (ESP_SLAVE_SLCHOST_BASE + 0x50)
#define ESP_SLAVE_INT_CLR_REG       (ESP_SLAVE_SLCHOST_BASE + 0xD4)
#define ESP_HOST_INT_ENA_REG        (ESP_SLAVE_SLCHOST_BASE + 0xDC)
#define ESP_SLAVE_PACKET_LEN_REG    (ESP_SLAVE_SLCHOST_BASE + 0x60)
#define ESP_SLAVE_TOKEN_RDATA       (ESP_SLAVE_SLCHOST_BASE + 0x44)
#define ESP_SLAVE_SCRATCH_REG_7     (ESP_SLAVE_SLCHOST_BASE + 0x8C)

#define SDIO_INT_NEW_PACKET         (23)

/* SDIO CCCR registers */

#define SD_IO_CCCR_FN_ENABLE        0x02
#define SD_IO_CCCR_FN_READY         0x03
#define SD_IO_CCCR_INT_ENABLE       0x04
#define SD_IO_CCCR_BUS_WIDTH        0x07
#define SD_IO_CCCR_BLKSIZEL         0x10
#define SD_IO_CCCR_BLKSIZEH         0x11

/* WiFi control commands */

#define ESP_HOSTED_CMD_SCAN         0x02
#define ESP_HOSTED_CMD_CONNECT      0x03
#define ESP_HOSTED_CMD_DISCONNECT   0x04
#define ESP_HOSTED_CMD_GET_MAC      0x05

/* Work queue timing */

#define WIFI_POLL_INTERVAL    MSEC2TICK(100)

/* Max scan results */

#define MAX_SCAN_RESULTS      16
#define MAX_SSID_LEN          32
#define MAX_PASSWORD_LEN      64

/****************************************************************************
 * Private Types
 ****************************************************************************/

/* esp_hosted payload header */

struct esp_payload_header_s
{
  uint8_t  if_type:4;
  uint8_t  if_num:4;
  uint8_t  flags;
  uint16_t len;
  uint16_t offset;
  uint16_t checksum;
  uint16_t seq_num;
  uint8_t  reserved[2];
} __attribute__((packed));

/* WiFi scan result */

struct wifi_scan_result_s
{
  char     ssid[MAX_SSID_LEN];
  uint8_t  bssid[6];
  int8_t   rssi;
  uint8_t  channel;
  uint8_t  authmode;
};

/* WiFi driver private data */

struct esp_wifi_dev_s
{
  struct net_driver_s  netdev;
  struct work_s        pollwork;
  bool                 ifup;
  bool                 connected;
  bool                 sdio_initialized;
  uint8_t              mac[6];
  uint8_t              rxbuf[2048];
  char                 ssid[MAX_SSID_LEN + 1];
  char                 password[MAX_PASSWORD_LEN];
  uint8_t              status;
  mutex_t              lock;

  /* SDIO context */

  sdmmc_card_t        *card;
  void                *sdio_bus_lock;
  uint16_t             seq_num;

  /* Scan results */

  struct wifi_scan_result_s scan_results[MAX_SCAN_RESULTS];
  int                  scan_count;
};

/****************************************************************************
 * Private Data
 ****************************************************************************/

static struct esp_wifi_dev_s g_wifi;

/****************************************************************************
 * Private Functions - SDIO Low Level
 ****************************************************************************/

/****************************************************************************
 * Name: sdio_cmd52_read
 ****************************************************************************/

static int sdio_cmd52_read(sdmmc_card_t *card, uint8_t func,
                           uint32_t addr, uint8_t *data)
{
  return sdmmc_io_read_byte(card, func, addr & ESP_ADDRESS_MASK, data);
}

/****************************************************************************
 * Name: sdio_cmd52_write
 ****************************************************************************/

static int sdio_cmd52_write(sdmmc_card_t *card, uint8_t func,
                            uint32_t addr, uint8_t data)
{
  return sdmmc_io_write_byte(card, func, addr & ESP_ADDRESS_MASK, data, NULL);
}

/****************************************************************************
 * Name: sdio_read_block
 ****************************************************************************/

static int sdio_read_block(sdmmc_card_t *card, uint32_t addr,
                           uint8_t *buf, uint16_t count)
{
  uint16_t remainder = count;
  uint16_t blocks;
  esp_err_t res;
  uint8_t *ptr = buf;

  while (remainder >= ESP_BLOCK_SIZE)
    {
      blocks = remainder / ESP_BLOCK_SIZE;
      res = sdmmc_io_read_blocks(card, 1, addr & ESP_ADDRESS_MASK,
                                 ptr, blocks * ESP_BLOCK_SIZE);
      if (res != ESP_OK)
        {
          return -EIO;
        }

      remainder -= blocks * ESP_BLOCK_SIZE;
      ptr += blocks * ESP_BLOCK_SIZE;
      addr += blocks * ESP_BLOCK_SIZE;
    }

  while (remainder > 0)
    {
      uint16_t chunk = remainder;
      res = sdmmc_io_read_bytes(card, 1, addr & ESP_ADDRESS_MASK, ptr, chunk);
      if (res != ESP_OK)
        {
          return -EIO;
        }

      remainder -= chunk;
      ptr += chunk;
      addr += chunk;
    }

  return count;
}

/****************************************************************************
 * Name: sdio_write_block
 ****************************************************************************/

static int sdio_write_block(sdmmc_card_t *card, uint32_t addr,
                            const uint8_t *buf, uint16_t count)
{
  uint16_t remainder = count;
  uint16_t blocks;
  esp_err_t res;
  const uint8_t *ptr = buf;

  while (remainder >= ESP_BLOCK_SIZE)
    {
      blocks = remainder / ESP_BLOCK_SIZE;
      res = sdmmc_io_write_blocks(card, 1, addr & ESP_ADDRESS_MASK,
                                  ptr, blocks * ESP_BLOCK_SIZE);
      if (res != ESP_OK)
        {
          return -EIO;
        }

      remainder -= blocks * ESP_BLOCK_SIZE;
      ptr += blocks * ESP_BLOCK_SIZE;
      addr += blocks * ESP_BLOCK_SIZE;
    }

  while (remainder > 0)
    {
      uint16_t chunk = remainder;
      res = sdmmc_io_write_bytes(card, 1, addr & ESP_ADDRESS_MASK, ptr, chunk);
      if (res != ESP_OK)
        {
          return -EIO;
        }

      remainder -= chunk;
      ptr += chunk;
      addr += chunk;
    }

  return count;
}

/****************************************************************************
 * Name: sdio_read_reg
 ****************************************************************************/

static int sdio_read_reg(sdmmc_card_t *card, uint32_t addr,
                         uint8_t *data, uint16_t size)
{
  if (size <= 1)
    {
      return sdmmc_io_read_byte(card, 1, addr & ESP_ADDRESS_MASK, data);
    }
  else
    {
      return sdmmc_io_read_bytes(card, 1, addr & ESP_ADDRESS_MASK, data, size);
    }
}

/****************************************************************************
 * Name: sdio_check_intr
 ****************************************************************************/

static bool sdio_check_intr(sdmmc_card_t *card, uint32_t intr_bit)
{
  uint32_t raw_intr = 0;
  int ret;

  ret = sdio_read_reg(card, ESP_SLAVE_INT_RAW_REG,
                      (uint8_t *)&raw_intr, 4);
  if (ret < 0)
    {
      return false;
    }

  return (raw_intr & (1 << intr_bit)) != 0;
}

/****************************************************************************
 * Name: sdio_clear_intr
 ****************************************************************************/

static void sdio_clear_intr(sdmmc_card_t *card, uint32_t intr_mask)
{
  sdio_write_reg(card, ESP_SLAVE_INT_CLR_REG,
                 (const uint8_t *)&intr_mask, 4);
}

/****************************************************************************
 * Name: sdio_get_packet_len
 ****************************************************************************/

static uint32_t sdio_get_packet_len(sdmmc_card_t *card)
{
  uint32_t len = 0;
  sdio_read_reg(card, ESP_SLAVE_PACKET_LEN_REG, (uint8_t *)&len, 4);
  return len & 0xFFFFF;
}

/****************************************************************************
 * Name: sdio_get_tx_buf_num
 ****************************************************************************/

static uint32_t sdio_get_tx_buf_num(sdmmc_card_t *card)
{
  uint32_t num = 0;
  sdio_read_reg(card, ESP_SLAVE_TOKEN_RDATA, (uint8_t *)&num, 4);
  return (num >> 16) & 0xFFF;
}

/****************************************************************************
 * Name: sdio_update_rx_count
 ****************************************************************************/

static void sdio_update_rx_count(sdmmc_card_t *card, uint32_t len)
{
  uint32_t count = 0;
  sdio_read_reg(card, 0x64, (uint8_t *)&count, 4);
  count += len;
  sdio_write_reg(card, 0x64, (const uint8_t *)&count, 4);
}

/****************************************************************************
 * Private Functions - SDIO Hardware Init
 ****************************************************************************/

/****************************************************************************
 * Name: sdio_init_hw
 ****************************************************************************/

static int sdio_init_hw(struct esp_wifi_dev_s *priv)
{
  esp_err_t res;
  int i;

  WIFI_INFO("Initializing SDIO hardware\n");

  /* Initialize SDMMC host */

  res = sdmmc_host_init();
  if (res != ESP_OK)
    {
      WIFI_ERR("sdmmc_host_init failed: %d\n", res);
      return -EIO;
    }

  /* Configure SDIO slot with GPIO matrix pins (SD2: GPIO14-19) */

  sdmmc_slot_config_t slot_config = SDMMC_SLOT_CONFIG_DEFAULT();
  slot_config.width = CONFIG_ESP32P4_WIFI_HOSTED_SDIO_BUS_WIDTH;
  slot_config.clk = CONFIG_ESP32P4_WIFI_HOSTED_SDIO_PIN_CLK;
  slot_config.cmd = CONFIG_ESP32P4_WIFI_HOSTED_SDIO_PIN_CMD;
  slot_config.d0  = CONFIG_ESP32P4_WIFI_HOSTED_SDIO_PIN_D0;
  slot_config.d1  = CONFIG_ESP32P4_WIFI_HOSTED_SDIO_PIN_D1;
  slot_config.d2  = CONFIG_ESP32P4_WIFI_HOSTED_SDIO_PIN_D2;
  slot_config.d3  = CONFIG_ESP32P4_WIFI_HOSTED_SDIO_PIN_D3;

  res = sdmmc_host_init_slot(CONFIG_ESP32P4_WIFI_HOSTED_SDIO_SLOT, &slot_config);
  if (res != ESP_OK)
    {
      WIFI_ERR("sdmmc_host_init_slot failed: %d\n", res);
      return -EIO;
    }

  /* Allocate card structure */

  priv->card = (sdmmc_card_t *)kmm_malloc(sizeof(sdmmc_card_t));
  if (!priv->card)
    {
      WIFI_ERR("Failed to allocate card structure\n");
      return -ENOMEM;
    }

  memset(priv->card, 0, sizeof(sdmmc_card_t));

  /* Initialize the SDIO card */

  sdmmc_host_t config = SDMMC_HOST_DEFAULT();
  config.slot = CONFIG_ESP32P4_WIFI_HOSTED_SDIO_SLOT;
  config.max_freq_khz = CONFIG_ESP32P4_WIFI_HOSTED_SDIO_FREQ_KHZ;
  config.flags |= SDMMC_HOST_FLAG_ALLOC_ALIGNED_BUF;

  res = sdmmc_card_init(&config, priv->card);
  if (res != ESP_OK)
    {
      WIFI_ERR("sdmmc_card_init failed: %d\n", res);
      kmm_free(priv->card);
      priv->card = NULL;
      return -EIO;
    }

  /* Enable SDIO function 1 */

  uint8_t ioe = 0;
  sdmmc_io_read_byte(priv->card, 0, SD_IO_CCCR_FN_ENABLE, &ioe);
  ioe |= 0x02;
  sdmmc_io_write_byte(priv->card, 0, SD_IO_CCCR_FN_ENABLE, ioe, &ioe);

  /* Wait for function 1 to be ready */

  for (i = 0; i < 10; i++)
    {
      uint8_t ior = 0;
      sdmmc_io_read_byte(priv->card, 0, SD_IO_CCCR_FN_READY, &ior);
      if (ior & 0x02)
        {
          break;
        }

      usleep(10 * 1000);
    }

  if (i >= 10)
    {
      WIFI_ERR("SDIO function 1 not ready\n");
      kmm_free(priv->card);
      priv->card = NULL;
      return -ETIMEDOUT;
    }

  /* Enable interrupts */

  uint8_t ie = 0;
  sdmmc_io_read_byte(priv->card, 0, SD_IO_CCCR_INT_ENABLE, &ie);
  ie |= 0x01 | 0x02;
  sdmmc_io_write_byte(priv->card, 0, SD_IO_CCCR_INT_ENABLE, ie, NULL);

  /* Set block size to 512 for both FN0 and FN1 */

  sdmmc_io_write_byte(priv->card, 0, SD_IO_CCCR_BLKSIZEL, 0x00, NULL);
  sdmmc_io_write_byte(priv->card, 0, SD_IO_CCCR_BLKSIZEH, 0x02, NULL);
  sdmmc_io_write_byte(priv->card, 0,
                      SD_IO_FBR_START + SD_IO_CCCR_BLKSIZEL, 0x00, NULL);
  sdmmc_io_write_byte(priv->card, 0,
                      SD_IO_FBR_START + SD_IO_CCCR_BLKSIZEH, 0x02, NULL);

  /* Set 4-bit bus width */

  sdmmc_io_write_byte(priv->card, 0, SD_IO_CCCR_BUS_WIDTH, 0x02, NULL);

  WIFI_INFO("SDIO hardware initialized (slot %d, %d-bit, %d KHz)\n",
            CONFIG_ESP32P4_WIFI_HOSTED_SDIO_SLOT,
            CONFIG_ESP32P4_WIFI_HOSTED_SDIO_BUS_WIDTH,
            CONFIG_ESP32P4_WIFI_HOSTED_SDIO_FREQ_KHZ);

  priv->sdio_initialized = true;
  return OK;
}

/****************************************************************************
 * Private Functions - esp_hosted Protocol
 ****************************************************************************/

/****************************************************************************
 * Name: esp_hosted_send_packet
 ****************************************************************************/

static int esp_hosted_send_packet(struct esp_wifi_dev_s *priv,
                                  uint8_t if_type, uint8_t if_num,
                                  const uint8_t *data, uint16_t len)
{
  struct esp_payload_header_s *hdr;
  uint8_t *sendbuf;
  uint16_t total_len;
  uint32_t buf_needed;
  uint32_t buf_available;
  int retries;
  int ret;

  if (!priv->sdio_initialized || !priv->card)
    {
      return -ENODEV;
    }

  total_len = ESP_PAYLOAD_HEADER_SIZE + len;
  sendbuf = (uint8_t *)kmm_malloc(total_len);
  if (!sendbuf)
    {
      return -ENOMEM;
    }

  /* Build payload header */

  hdr = (struct esp_payload_header_s *)sendbuf;
  memset(hdr, 0, ESP_PAYLOAD_HEADER_SIZE);
  hdr->if_type = if_type & 0x0F;
  hdr->if_num  = if_num & 0x0F;
  hdr->len     = len;
  hdr->offset  = ESP_PAYLOAD_HEADER_SIZE;
  hdr->seq_num = priv->seq_num++;

  memcpy(sendbuf + ESP_PAYLOAD_HEADER_SIZE, data, len);

  /* Check TX buffer availability */

  nxmutex_lock(&priv->lock);

  for (retries = 50; retries > 0; retries--)
    {
      buf_available = sdio_get_tx_buf_num(priv->card);
      buf_needed = (total_len + ESP_BLOCK_SIZE - 1) / ESP_BLOCK_SIZE;

      if (buf_available >= buf_needed)
        {
          break;
        }

      usleep(400);
    }

  if (retries == 0)
    {
      nxmutex_unlock(&priv->lock);
      kmm_free(sendbuf);
      return -EBUSY;
    }

  /* Write data to SDIO */

  ret = sdio_write_block(priv->card,
                         ESP_SLAVE_CMD53_END_ADDR - total_len,
                         sendbuf, total_len);

  nxmutex_unlock(&priv->lock);
  kmm_free(sendbuf);

  return (ret < 0) ? ret : OK;
}

/****************************************************************************
 * Name: esp_hosted_recv_packet
 ****************************************************************************/

static int esp_hosted_recv_packet(struct esp_wifi_dev_s *priv,
                                  uint8_t *if_type, uint8_t *if_num,
                                  uint8_t *data, uint16_t max_len)
{
  struct esp_payload_header_s hdr;
  uint32_t len_from_slave;
  int ret;

  if (!priv->sdio_initialized || !priv->card)
    {
      return -ENODEV;
    }

  /* Check for new packet interrupt */

  if (!sdio_check_intr(priv->card, SDIO_INT_NEW_PACKET))
    {
      return 0;
    }

  /* Get packet length */

  len_from_slave = sdio_get_packet_len(priv->card);
  if (len_from_slave == 0)
    {
      return 0;
    }

  if (len_from_slave > ESP_RX_BUFFER_SIZE)
    {
      sdio_clear_intr(priv->card, 1 << SDIO_INT_NEW_PACKET);
      return -E2BIG;
    }

  /* Read header first */

  ret = sdio_read_block(priv->card, ESP_SLAVE_CMD53_END_ADDR,
                        (uint8_t *)&hdr, ESP_PAYLOAD_HEADER_SIZE);
  if (ret < ESP_PAYLOAD_HEADER_SIZE)
    {
      return 0;
    }

  /* Validate header */

  if (hdr.len == 0 || hdr.offset != ESP_PAYLOAD_HEADER_SIZE ||
      hdr.len > max_len)
    {
      sdio_clear_intr(priv->card, 1 << SDIO_INT_NEW_PACKET);
      return 0;
    }

  /* Read payload */

  ret = sdio_read_block(priv->card,
                        ESP_SLAVE_CMD53_END_ADDR + hdr.offset,
                        data, hdr.len);

  /* Update RX byte count */

  sdio_update_rx_count(priv->card, len_from_slave);

  /* Clear interrupt */

  sdio_clear_intr(priv->card, 1 << SDIO_INT_NEW_PACKET);

  if (if_type)
    {
      *if_type = hdr.if_type;
    }

  if (if_num)
    {
      *if_num = hdr.if_num;
    }

  return hdr.len;
}

/****************************************************************************
 * Name: esp_hosted_init_protocol
 ****************************************************************************/

static int esp_hosted_init_protocol(struct esp_wifi_dev_s *priv)
{
  /* Get MAC address from slave scratch registers */

  uint8_t mac_buf[6];
  int ret;

  /* Read MAC from scratch registers 0-5 */

  ret = sdio_read_reg(priv->card, ESP_SLAVE_SCRATCH_REG_0, mac_buf, 6);
  if (ret >= 0 && (mac_buf[0] != 0 || mac_buf[1] != 0 || mac_buf[2] != 0))
    {
      memcpy(priv->mac, mac_buf, 6);
      WIFI_INFO("MAC from slave: %02x:%02x:%02x:%02x:%02x:%02x\n",
                priv->mac[0], priv->mac[1], priv->mac[2],
                priv->mac[3], priv->mac[4], priv->mac[5]);
    }
  else
    {
      /* Use default MAC */

      priv->mac[0] = 0x02;
      priv->mac[1] = 0x00;
      priv->mac[2] = 0x00;
      priv->mac[3] = 0x00;
      priv->mac[4] = 0x00;
      priv->mac[5] = 0x01;
      WIFI_INFO("Using default MAC\n");
    }

  return OK;
}

/****************************************************************************
 * Private Functions - Network Device Callbacks
 ****************************************************************************/

/****************************************************************************
 * Name: esp_wifi_ifup
 ****************************************************************************/

static int esp_wifi_ifup(FAR struct net_driver_s *dev)
{
  FAR struct esp_wifi_dev_s *priv =
    (FAR struct esp_wifi_dev_s *)dev->d_private;

  WIFI_INFO("Bringing up WiFi interface\n");

  if (!priv->sdio_initialized)
    {
      int ret = sdio_init_hw(priv);
      if (ret < 0)
        {
          WIFI_ERR("SDIO init failed: %d\n", ret);
          return ret;
        }

      esp_hosted_init_protocol(priv);
    }

  priv->ifup = true;
  work_queue(LPWORK, &priv->pollwork, esp_wifi_poll_work,
             priv, WIFI_POLL_INTERVAL);

  return OK;
}

/****************************************************************************
 * Name: esp_wifi_ifdown
 ****************************************************************************/

static int esp_wifi_ifdown(FAR struct net_driver_s *dev)
{
  FAR struct esp_wifi_dev_s *priv =
    (FAR struct esp_wifi_dev_s *)dev->d_private;

  WIFI_INFO("Bringing down WiFi interface\n");
  work_cancel(LPWORK, &priv->pollwork);
  priv->ifup = false;
  priv->connected = false;
  netdev_carrier_off(dev);

  return OK;
}

/****************************************************************************
 * Name: esp_wifi_transmit
 ****************************************************************************/

static int esp_wifi_transmit(FAR struct net_driver_s *dev)
{
  FAR struct esp_wifi_dev_s *priv =
    (FAR struct esp_wifi_dev_s *)dev->d_private;
  int ret;

  ret = esp_hosted_send_packet(priv, ESP_STA_IF, 0,
                               dev->d_buf, dev->d_len);
  if (ret < 0)
    {
      WIFI_ERR("TX failed: %d\n", ret);
    }

  return ret;
}

/****************************************************************************
 * Name: esp_wifi_txavail
 ****************************************************************************/

static int esp_wifi_txavail(FAR struct net_driver_s *dev)
{
  if (dev->d_buf != NULL && dev->d_len > 0)
    {
      return esp_wifi_transmit(dev);
    }

  return OK;
}

