/****************************************************************************
 * Name: esp_wifi_ioctl
 ****************************************************************************/

#ifdef CONFIG_NETDEV_IOCTL
static int esp_wifi_ioctl(FAR struct net_driver_s *dev, int cmd,
                          unsigned long arg)
{
  FAR struct esp_wifi_dev_s *priv =
    (FAR struct esp_wifi_dev_s *)dev->d_private;
  int ret = -ENOTTY;

  switch (cmd)
    {
      case SIOCSIWESSID:
        {
          struct iwreq *iwr = (struct iwreq *)arg;
          if (iwr && iwr->u.essid.pointer)
            {
              int len = iwr->u.essid.length;
              if (len > MAX_SSID_LEN) len = MAX_SSID_LEN;
              memset(priv->ssid, 0, sizeof(priv->ssid));
              memcpy(priv->ssid, iwr->u.essid.pointer, len);

              /* Send connect command to slave */

              uint8_t cmd_buf[128];
              cmd_buf[0] = ESP_HOSTED_CMD_CONNECT;
              cmd_buf[1] = (uint8_t)len;
              memcpy(cmd_buf + 2, priv->ssid, len);
              int pwd_len = strlen(priv->password);
              cmd_buf[2 + len] = (uint8_t)pwd_len;
              memcpy(cmd_buf + 3 + len, priv->password, pwd_len);

              esp_hosted_send_packet(priv, 5, 0,
                                     cmd_buf, 3 + len + pwd_len);

              WIFI_INFO("Connecting to '%s'\n", priv->ssid);
              priv->connected = true;
              priv->status = 1;
              netdev_carrier_on(dev);
              ret = OK;
            }
        }
        break;

      case SIOCGIWESSID:
        {
          struct iwreq *iwr = (struct iwreq *)arg;
          if (iwr && iwr->u.essid.pointer)
            {
              strncpy(iwr->u.essid.pointer, priv->ssid,
                      iwr->u.essid.length - 1);
              iwr->u.essid.length = strlen(priv->ssid);
              ret = OK;
            }
        }
        break;

      case SIOCSIWSCAN:
        {
          /* Send scan command to slave */

          uint8_t cmd_buf[4];
          cmd_buf[0] = ESP_HOSTED_CMD_SCAN;
          esp_hosted_send_packet(priv, 5, 0, cmd_buf, 1);

          priv->scan_count = 0;
          WIFI_INFO("Scan started\n");
          ret = OK;
        }
        break;

      case SIOCGIWSCAN:
        ret = priv->scan_count;
        break;

      case SIOCSIWENCODEEXT:
        {
          struct iwreq *iwr = (struct iwreq *)arg;
          if (iwr && iwr->u.encoding.pointer)
            {
              int len = iwr->u.encoding.length;
              if (len > MAX_PASSWORD_LEN - 1) len = MAX_PASSWORD_LEN - 1;
              memset(priv->password, 0, sizeof(priv->password));
              memcpy(priv->password, iwr->u.encoding.pointer, len);
              ret = OK;
            }
        }
        break;

      case SIOCSIWAUTH:
      case SIOCSIWGENIE:
      case SIOCSIWPMKSA:
      case SIOCSIWMODE:
      case SIOCSIWFREQ:
      case SIOCSIWRATE:
      case SIOCSIWRTS:
      case SIOCSIWFRAG:
      case SIOCSIWTXPOW:
      case SIOCSIWRETRY:
      case SIOCSIWPOWER:
        ret = OK;
        break;

      case SIOCGIWMODE:
        {
          int *mode = (int *)arg;
          if (mode)
            {
              *mode = IW_MODE_INFRA;
              ret = OK;
            }
        }
        break;

      default:
        WIFI_DBG("Unknown ioctl 0x%x\n", cmd);
        break;
    }

  return ret;
}
#endif

/****************************************************************************
 * Name: esp_wifi_poll_work
 ****************************************************************************/

static void esp_wifi_poll_work(FAR void *arg)
{
  FAR struct esp_wifi_dev_s *priv = (FAR struct esp_wifi_dev_s *)arg;
  uint8_t if_type;
  uint8_t if_num;
  int len;

  if (!priv->ifup || !priv->sdio_initialized)
    {
      return;
    }

  /* Try to receive data from SDIO */

  len = esp_hosted_recv_packet(priv, &if_type, &if_num,
                               priv->rxbuf, sizeof(priv->rxbuf));
  if (len > 0 && if_type == ESP_STA_IF)
    {
      /* Pass received packet to the network stack */

      struct net_driver_s *dev = &priv->netdev;
      dev->d_buf = priv->rxbuf;
      dev->d_len = len;

#ifdef CONFIG_NET_IPv4
      ipv4_input(dev);
#endif

      dev->d_buf = NULL;
      dev->d_len = 0;
    }

  /* Re-schedule poll work */

  if (priv->ifup)
    {
      work_queue(LPWORK, &priv->pollwork, esp_wifi_poll_work,
                 priv, WIFI_POLL_INTERVAL);
    }
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: esp_hosted_wifi_init
 ****************************************************************************/

int esp_hosted_wifi_init(void)
{
  int ret;

  WIFI_INFO("Initializing esp_hosted WiFi driver\n");

  memset(&g_wifi, 0, sizeof(g_wifi));
  nxmutex_init(&g_wifi.lock);

  /* Set default MAC */

  g_wifi.mac[0] = 0x02;
  g_wifi.mac[1] = 0x00;
  g_wifi.mac[2] = 0x00;
  g_wifi.mac[3] = 0x00;
  g_wifi.mac[4] = 0x00;
  g_wifi.mac[5] = 0x01;

  /* Configure network device */

  g_wifi.netdev.d_ifup    = esp_wifi_ifup;
  g_wifi.netdev.d_ifdown  = esp_wifi_ifdown;
  g_wifi.netdev.d_txavail = esp_wifi_txavail;
#ifdef CONFIG_NETDEV_IOCTL
  g_wifi.netdev.d_ioctl   = esp_wifi_ioctl;
#endif
#ifdef CONFIG_NET_MCASTGROUP
  g_wifi.netdev.d_addmac  = esp_wifi_addmac;
  g_wifi.netdev.d_rmmac   = esp_wifi_rmmac;
#endif
  g_wifi.netdev.d_private = &g_wifi;

  memcpy(g_wifi.netdev.d_mac.ether.ether_addr_octet, g_wifi.mac, 6);

  /* Register network device */

  ret = netdev_register(&g_wifi.netdev, NET_LL_IEEE80211);
  if (ret < 0)
    {
      WIFI_ERR("netdev_register failed: %d\n", ret);
      return ret;
    }

  WIFI_INFO("WiFi driver registered as wlan0\n");
  return OK;
}

