/*
 * SPDX-License-Identifier: Apache-2.0
 *
 * esp_hosted WiFi driver for NuttX on ESP32-P4.
 * Uses esp-hal-3rdparty low-level HAL (sdmmc_ll.h) for SDIO communication.
 */

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/arch.h>
#include <nuttx/net/netdev.h>
#include <nuttx/net/ip.h>
#include <nuttx/wqueue.h>
#include <nuttx/clock.h>
#include <nuttx/mutex.h>
#include <nuttx/wireless/wireless.h>
#include <nuttx/kmalloc.h>
#include <debug.h>
#include <errno.h>
#include <string.h>
#include <syslog.h>
#include <stdio.h>

#include <net/if.h>
#include <net/if_arp.h>
#include <arpa/inet.h>

#include "esp_hosted_wifi.h"

/* Define __DECLARE_RCC_ATOMIC_ENV as empty for NuttX (no FreeRTOS critical section) */

#define __DECLARE_RCC_ATOMIC_ENV

/* esp-hal-3rdparty low-level HAL */

#include "hal/sdmmc_ll.h"
#include "hal/sdmmc_hal.h"
#include "soc/sdmmc_struct.h"
#include "soc/sdmmc_reg.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define TAG  "esp_wifi"
#define WIFI_ERR(...)   syslog(LOG_ERR, TAG ": " __VA_ARGS__)
#define WIFI_INFO(...)  syslog(LOG_INFO, TAG ": " __VA_ARGS__)
#define WIFI_DBG(...)   syslog(LOG_DEBUG, TAG ": " __VA_ARGS__)

/* esp_hosted protocol definitions */

#define ESP_STA_IF                  1
#define ESP_PAYLOAD_HEADER_SIZE     12
#define ESP_SLAVE_CMD53_END_ADDR    0x1F800
#define ESP_BLOCK_SIZE              512
#define ESP_RX_BUFFER_SIZE          1536
#define ESP_ADDRESS_MASK            0x3FF

/* SDIO slave register addresses */

#define ESP_SLAVE_SLCHOST_BASE      0x3FF55000
#define ESP_SLAVE_INT_RAW_REG       (ESP_SLAVE_SLCHOST_BASE + 0x50)
#define ESP_SLAVE_INT_CLR_REG       (ESP_SLAVE_SLCHOST_BASE + 0xD4)
#define ESP_HOST_INT_ENA_REG        (ESP_SLAVE_SLCHOST_BASE + 0xDC)
#define ESP_SLAVE_PACKET_LEN_REG    (ESP_SLAVE_SLCHOST_BASE + 0x60)
#define ESP_SLAVE_TOKEN_RDATA       (ESP_SLAVE_SLCHOST_BASE + 0x44)
#define ESP_SLAVE_SCRATCH_REG_7     (ESP_SLAVE_SLCHOST_BASE + 0x8C)

#define SDIO_INT_NEW_PACKET         (23)

/* SDIO CCCR registers */

#define SD_IO_CCCR_FN_ENABLE        0x02
#define SD_IO_CCCR_FN_READY         0x03
#define SD_IO_CCCR_INT_ENABLE       0x04
#define SD_IO_CCCR_BUS_WIDTH        0x07
#define SD_IO_CCCR_BLKSIZEL         0x10
#define SD_IO_CCCR_BLKSIZEH         0x11
#define SD_IO_FBR_START             0x100

/* SDIO command definitions */

#define SD_CMD_GO_IDLE_STATE        0
#define SD_CMD_SEND_OP_COND         5
#define SD_CMD_SEND_RELATIVE_ADDR   3
#define SD_CMD_SELECT_CARD          7
#define SD_CMD_IO_RW_DIRECT         52
#define SD_CMD_IO_RW_EXTENDED       53

/* CMD52 argument fields */

#define CMD52_FUNC(x)       (((x) & 0x7) << 28)
#define CMD52_OP_WRITE      (1 << 31)
#define CMD52_REG_ADDR(x)   (((x) & 0x1FFFF) << 9)

/* CMD53 argument fields */

#define CMD53_FUNC(x)       (((x) & 0x7) << 28)
#define CMD53_OP_WRITE      (1 << 31)
#define CMD53_REG_ADDR(x)   (((x) & 0x1FFFF) << 9)
#define CMD53_COUNT(x)      (((x) & 0x1FF))

/* Work queue timing */

#define WIFI_POLL_INTERVAL    MSEC2TICK(100)

/* Max scan results */

#define MAX_SCAN_RESULTS      16
#define MAX_SSID_LEN          32
#define MAX_PASSWORD_LEN      64

/****************************************************************************
 * Private Types
 ****************************************************************************/

/* esp_hosted payload header */

struct esp_payload_header_s
{
  uint8_t  if_type:4;
  uint8_t  if_num:4;
  uint8_t  flags;
  uint16_t len;
  uint16_t offset;
  uint16_t checksum;
  uint16_t seq_num;
  uint8_t  reserved[2];
} __attribute__((packed));

/* WiFi driver private data */

struct esp_wifi_dev_s
{
  struct net_driver_s  netdev;
  struct work_s        pollwork;
  bool                 ifup;
  bool                 connected;
  bool                 sdio_initialized;
  uint8_t              mac[6];
  uint8_t              rxbuf[2048];
  char                 ssid[MAX_SSID_LEN + 1];
  char                 password[MAX_PASSWORD_LEN];
  uint8_t              status;
  mutex_t              lock;
  uint16_t             seq_num;
  uint16_t             rca;
  sdmmc_hal_context_t  hal;
};

/****************************************************************************
 * Private Function Prototypes
 ****************************************************************************/

static void esp_wifi_poll_work(FAR void *arg);

/****************************************************************************
 * Private Data
 ****************************************************************************/

static struct esp_wifi_dev_s g_wifi;

/****************************************************************************
 * Private Functions - SDMMC Low Level
 ****************************************************************************/

/****************************************************************************
 * Name: sdmmc_send_cmd
 ****************************************************************************/

static int sdmmc_send_cmd(sdmmc_dev_t *hw, uint32_t cmd, uint32_t arg,
                          uint32_t *resp, bool need_response)
{
  int timeout;

  /* Wait for controller not busy */

  timeout = 100;
  while (hw->status.card_data_busy && timeout-- > 0)
    {
      up_mdelay(1);
    }

  /* Clear pending interrupts */

  hw->rintsts.val = 0xFFFFFFFF;

  /* Set argument */

  hw->cmdarg = arg;

  /* Build command register value */

  sdmmc_hw_cmd_t cmd_val;
  cmd_val.val = 0;
  cmd_val.cmd_index = cmd & 0x3F;
  cmd_val.response_expect = need_response ? 1 : 0;
  cmd_val.check_response_crc = need_response ? 1 : 0;
  cmd_val.data_expected = 0;
  cmd_val.rw = 0;
  cmd_val.send_init = (cmd == 0) ? 1 : 0;
  cmd_val.wait_complete = 1;
  cmd_val.card_num = 0;
  cmd_val.start_command = 1;

  hw->cmd = cmd_val;

  /* Wait for command done */

  timeout = 100;
  while (hw->cmd.start_command && timeout-- > 0)
    {
      up_mdelay(1);
    }

  if (timeout <= 0)
    {
      return -ETIMEDOUT;
    }

  /* Check for errors */

  uint32_t rint = hw->rintsts.val;
  if (rint & (1 << 1))  /* Response error */
    {
      return -EIO;
    }

  if (rint & (1 << 8))  /* Response timeout */
    {
      return -ETIMEDOUT;
    }

  /* Read response if requested */

  if (resp != NULL && need_response)
    {
      *resp = hw->resp[0];
    }

  return OK;
}

/****************************************************************************
 * Name: sdio_cmd52_read
 ****************************************************************************/

static int sdio_cmd52_read(sdmmc_dev_t *hw, uint8_t func,
                           uint32_t addr, uint8_t *data)
{
  uint32_t arg;
  uint32_t resp;
  int ret;

  arg = CMD52_FUNC(func) | CMD52_REG_ADDR(addr);
  ret = sdmmc_send_cmd(hw, SD_CMD_IO_RW_DIRECT, arg, &resp, true);
  if (ret < 0)
    {
      return ret;
    }

  if (data != NULL)
    {
      *data = (resp >> 8) & 0xFF;
    }

  return OK;
}

/****************************************************************************
 * Name: sdio_cmd52_write
 ****************************************************************************/

static int sdio_cmd52_write(sdmmc_dev_t *hw, uint8_t func,
                            uint32_t addr, uint8_t data)
{
  uint32_t arg;
  uint32_t resp;

  arg = CMD52_OP_WRITE | CMD52_FUNC(func) | CMD52_REG_ADDR(addr) | data;
  return sdmmc_send_cmd(hw, SD_CMD_IO_RW_DIRECT, arg, &resp, true);
}

/****************************************************************************
 * Name: sdio_cmd53_read
 ****************************************************************************/

static int sdio_cmd53_read(sdmmc_dev_t *hw, uint8_t func, uint32_t addr,
                           uint8_t *buf, uint16_t count)
{
  uint32_t arg;
  uint32_t resp;
  int i;
  int timeout;

  /* Configure block size and byte count */

  sdmmc_ll_set_block_size(hw, count);
  sdmmc_ll_set_data_transfer_len(hw, count);

  /* Build CMD53 argument: read, byte mode */

  arg = CMD53_FUNC(func) | CMD53_REG_ADDR(addr) | CMD53_COUNT(count);

  /* Build command */

  sdmmc_hw_cmd_t cmd_val;
  cmd_val.val = 0;
  cmd_val.cmd_index = SD_CMD_IO_RW_EXTENDED;
  cmd_val.response_expect = 1;
  cmd_val.check_response_crc = 1;
  cmd_val.data_expected = 1;
  cmd_val.rw = 0;  /* Read */
  cmd_val.wait_complete = 1;
  cmd_val.card_num = 0;
  cmd_val.start_command = 1;

  hw->cmdarg = arg;
  hw->cmd = cmd_val;

  /* Wait for command done */

  timeout = 100;
  while (hw->cmd.start_command && timeout-- > 0)
    {
      up_mdelay(1);
    }

  if (timeout <= 0)
    {
      return -ETIMEDOUT;
    }

  /* Wait for data ready (FIFO not empty) */

  timeout = 500;
  while (hw->status.data_state_machine_busy && timeout-- > 0)
    {
      up_mdelay(1);
    }

  /* Read data from FIFO */

  for (i = 0; i < (count + 3) / 4; i++)
    {
      uint32_t word = hw->data;
      int j;
      for (j = 0; j < 4 && (i * 4 + j) < count; j++)
        {
          buf[i * 4 + j] = (word >> (j * 8)) & 0xFF;
        }
    }

  return count;
}

/****************************************************************************
 * Name: sdio_cmd53_write
 ****************************************************************************/

static int sdio_cmd53_write(sdmmc_dev_t *hw, uint8_t func, uint32_t addr,
                            const uint8_t *buf, uint16_t count)
{
  uint32_t arg;
  int i;
  int timeout;

  /* Configure block size and byte count */

  sdmmc_ll_set_block_size(hw, count);
  sdmmc_ll_set_data_transfer_len(hw, count);

  /* Write data to FIFO before sending command */

  for (i = 0; i < (count + 3) / 4; i++)
    {
      uint32_t word = 0;
      int j;
      for (j = 0; j < 4 && (i * 4 + j) < count; j++)
        {
          word |= ((uint32_t)buf[i * 4 + j]) << (j * 8);
        }
      hw->data = word;
    }

  /* Build CMD53 argument: write, byte mode */

  arg = CMD53_OP_WRITE | CMD53_FUNC(func) |
        CMD53_REG_ADDR(addr) | CMD53_COUNT(count);

  sdmmc_hw_cmd_t cmd_val;
  cmd_val.val = 0;
  cmd_val.cmd_index = SD_CMD_IO_RW_EXTENDED;
  cmd_val.response_expect = 1;
  cmd_val.check_response_crc = 1;
  cmd_val.data_expected = 1;
  cmd_val.rw = 1;  /* Write */
  cmd_val.wait_complete = 1;
  cmd_val.card_num = 0;
  cmd_val.start_command = 1;

  hw->cmdarg = arg;
  hw->cmd = cmd_val;

  /* Wait for command done */

  timeout = 100;
  while (hw->cmd.start_command && timeout-- > 0)
    {
      up_mdelay(1);
    }

  if (timeout <= 0)
    {
      return -ETIMEDOUT;
    }

  return count;
}

/****************************************************************************
 * Name: sdio_read_reg
 ****************************************************************************/

static int sdio_read_reg(sdmmc_dev_t *hw, uint32_t addr,
                         uint8_t *data, uint16_t size)
{
  if (size <= 1)
    {
      return sdio_cmd52_read(hw, 1, addr & ESP_ADDRESS_MASK, data);
    }
  else
    {
      return sdio_cmd53_read(hw, 1, addr & ESP_ADDRESS_MASK, data, size);
    }
}

/****************************************************************************
 * Name: sdio_write_reg
 ****************************************************************************/

static int sdio_write_reg(sdmmc_dev_t *hw, uint32_t addr,
                          const uint8_t *data, uint16_t size)
{
  if (size <= 1)
    {
      return sdio_cmd52_write(hw, 1, addr & ESP_ADDRESS_MASK, *data);
    }
  else
    {
      return sdio_cmd53_write(hw, 1, addr & ESP_ADDRESS_MASK, data, size);
    }
}

/****************************************************************************
 * Name: sdio_check_intr
 ****************************************************************************/

static bool sdio_check_intr(sdmmc_dev_t *hw, uint32_t intr_bit)
{
  uint32_t raw_intr = 0;
  int ret;

  ret = sdio_read_reg(hw, ESP_SLAVE_INT_RAW_REG,
                      (uint8_t *)&raw_intr, 4);
  if (ret < 0)
    {
      return false;
    }

  return (raw_intr & (1 << intr_bit)) != 0;
}

/****************************************************************************
 * Name: sdio_clear_intr
 ****************************************************************************/

static void sdio_clear_intr(sdmmc_dev_t *hw, uint32_t intr_mask)
{
  sdio_write_reg(hw, ESP_SLAVE_INT_CLR_REG,
                 (const uint8_t *)&intr_mask, 4);
}

/****************************************************************************
 * Name: sdio_get_packet_len
 ****************************************************************************/

static uint32_t sdio_get_packet_len(sdmmc_dev_t *hw)
{
  uint32_t len = 0;
  sdio_read_reg(hw, ESP_SLAVE_PACKET_LEN_REG, (uint8_t *)&len, 4);
  return len & 0xFFFFF;
}

/****************************************************************************
 * Name: sdio_get_tx_buf_num
 ****************************************************************************/

static uint32_t sdio_get_tx_buf_num(sdmmc_dev_t *hw)
{
  uint32_t num = 0;
  sdio_read_reg(hw, ESP_SLAVE_TOKEN_RDATA, (uint8_t *)&num, 4);
  return (num >> 16) & 0xFFF;
}

/****************************************************************************
 * Name: sdio_update_rx_count
 ****************************************************************************/

static void sdio_update_rx_count(sdmmc_dev_t *hw, uint32_t len)
{
  uint32_t count = 0;
  sdio_read_reg(hw, 0x64, (uint8_t *)&count, 4);
  count += len;
  sdio_write_reg(hw, 0x64, (const uint8_t *)&count, 4);
}

/****************************************************************************
 * Private Functions - SDIO Hardware Init
 ****************************************************************************/

/****************************************************************************
 * Name: sdio_init_hw
 ****************************************************************************/

static int sdio_init_hw(struct esp_wifi_dev_s *priv)
{
  sdmmc_dev_t *hw;
  uint32_t resp;
  int timeout;
  int i;

  WIFI_INFO("Initializing SDIO hardware\n");

  /* Initialize SDMMC HAL */

  sdmmc_hal_init(&priv->hal);
  hw = (sdmmc_dev_t *)priv->hal.dev;

  /* Enable SDMMC bus clock */

  sdmmc_ll_enable_bus_clock(0, true);
  sdmmc_ll_reset_register(0);

  /* Reset controller */

  sdmmc_ll_reset_controller(hw);
  timeout = 100;
  while (!sdmmc_ll_is_controller_reset_done(hw) && timeout-- > 0)
    {
      up_mdelay(1);
    }

  sdmmc_ll_reset_dma(hw);
  sdmmc_ll_reset_fifo(hw);

  /* Configure clock for 400kHz identification mode */

  sdmmc_ll_select_clk_source(hw, SDMMC_CLK_SRC_DEFAULT);
  sdmmc_ll_set_clock_div(hw, 200);
  sdmmc_ll_enable_card_clock(hw, 0, true);

  /* Set timeouts */

  sdmmc_ll_set_response_timeout(hw, 0xFFFFFF);
  sdmmc_ll_set_data_timeout(hw, 0xFFFFFF);

  /* Set card width to 1-bit initially */

  sdmmc_ll_set_card_width(hw, 0, SD_BUS_WIDTH_1_BIT);

  /* Init DMA and phase delay */

  sdmmc_ll_init_dma(hw);
  sdmmc_ll_init_phase_delay(hw);

  WIFI_INFO("SDMMC controller configured\n");

  /* Send CMD0 (GO_IDLE_STATE) */

  sdmmc_send_cmd(hw, SD_CMD_GO_IDLE_STATE, 0, NULL, false);
  up_mdelay(10);

  /* Send CMD5 (IO_SEND_OP_COND) to detect SDIO card */

  sdmmc_send_cmd(hw, SD_CMD_SEND_OP_COND, 0, &resp, true);
  WIFI_INFO("CMD5 resp=0x%08lx\n", (unsigned long)resp);

  /* Send CMD5 with voltage window */

  sdmmc_send_cmd(hw, SD_CMD_SEND_OP_COND, 0x00FF8000, &resp, true);
  up_mdelay(10);

  /* Send CMD3 (SEND_RELATIVE_ADDR) */

  sdmmc_send_cmd(hw, SD_CMD_SEND_RELATIVE_ADDR, 0, &resp, true);
  priv->rca = (resp >> 16) & 0xFFFF;
  WIFI_INFO("CMD3 RCA=0x%04x\n", priv->rca);

  /* Send CMD7 (SELECT_CARD) */

  sdmmc_send_cmd(hw, SD_CMD_SELECT_CARD,
                 ((uint32_t)priv->rca) << 16, &resp, true);

  /* Enable SDIO function 1 */

  sdio_cmd52_write(hw, 0, SD_IO_CCCR_FN_ENABLE, 0x02);

  /* Wait for function 1 to be ready */

  for (i = 0; i < 10; i++)
    {
      uint8_t ready = 0;
      sdio_cmd52_read(hw, 0, SD_IO_CCCR_FN_READY, &ready);
      if (ready & 0x02)
        {
          break;
        }
      up_mdelay(10);
    }

  if (i >= 10)
    {
      WIFI_ERR("SDIO function 1 not ready\n");
      return -ETIMEDOUT;
    }

  /* Enable interrupts */

  sdio_cmd52_write(hw, 0, SD_IO_CCCR_INT_ENABLE, 0x01 | 0x02);

  /* Set block size to 512 */

  sdio_cmd52_write(hw, 0, SD_IO_CCCR_BLKSIZEL, 0x00);
  sdio_cmd52_write(hw, 0, SD_IO_CCCR_BLKSIZEH, 0x02);
  sdio_cmd52_write(hw, 0, SD_IO_FBR_START + SD_IO_CCCR_BLKSIZEL, 0x00);
  sdio_cmd52_write(hw, 0, SD_IO_FBR_START + SD_IO_CCCR_BLKSIZEH, 0x02);

  /* Set 4-bit bus width */

  sdio_cmd52_write(hw, 0, SD_IO_CCCR_BUS_WIDTH, 0x02);
  sdmmc_ll_set_card_width(hw, 0, SD_BUS_WIDTH_4_BIT);

  /* Increase clock speed to 20MHz */

  sdmmc_ll_set_clock_div(hw, 4);

  WIFI_INFO("SDIO hardware initialized\n");
  priv->sdio_initialized = true;
  return OK;
}

/****************************************************************************
 * Private Functions - esp_hosted Protocol
 ****************************************************************************/

/****************************************************************************
 * Name: esp_hosted_send_packet
 ****************************************************************************/

static int esp_hosted_send_packet(struct esp_wifi_dev_s *priv,
                                  uint8_t if_type, uint8_t if_num,
                                  const uint8_t *data, uint16_t len)
{
  struct esp_payload_header_s *hdr;
  uint8_t *sendbuf;
  uint16_t total_len;
  uint32_t buf_available;
  int retries;
  int ret;
  sdmmc_dev_t *hw = (sdmmc_dev_t *)priv->hal.dev;

  if (!priv->sdio_initialized)
    {
      return -ENODEV;
    }

  total_len = ESP_PAYLOAD_HEADER_SIZE + len;
  sendbuf = (uint8_t *)kmm_malloc(total_len);
  if (!sendbuf)
    {
      return -ENOMEM;
    }

  /* Build payload header */

  hdr = (struct esp_payload_header_s *)sendbuf;
  memset(hdr, 0, ESP_PAYLOAD_HEADER_SIZE);
  hdr->if_type = if_type & 0x0F;
  hdr->if_num  = if_num & 0x0F;
  hdr->len     = len;
  hdr->offset  = ESP_PAYLOAD_HEADER_SIZE;
  hdr->seq_num = priv->seq_num++;

  memcpy(sendbuf + ESP_PAYLOAD_HEADER_SIZE, data, len);

  /* Check TX buffer availability */

  nxmutex_lock(&priv->lock);

  for (retries = 50; retries > 0; retries--)
    {
      buf_available = sdio_get_tx_buf_num(hw);
      if (buf_available > 0)
        {
          break;
        }
      usleep(400);
    }

  if (retries == 0)
    {
      nxmutex_unlock(&priv->lock);
      kmm_free(sendbuf);
      return -EBUSY;
    }

  /* Write data to SDIO */

  ret = sdio_cmd53_write(hw, 1,
                         ESP_SLAVE_CMD53_END_ADDR - total_len,
                         sendbuf, total_len);

  nxmutex_unlock(&priv->lock);
  kmm_free(sendbuf);

  return (ret < 0) ? ret : OK;
}

/****************************************************************************
 * Name: esp_hosted_recv_packet
 ****************************************************************************/

static int esp_hosted_recv_packet(struct esp_wifi_dev_s *priv,
                                  uint8_t *if_type, uint8_t *if_num,
                                  uint8_t *data, uint16_t max_len)
{
  struct esp_payload_header_s hdr;
  uint32_t len_from_slave;
  int ret;
  sdmmc_dev_t *hw = (sdmmc_dev_t *)priv->hal.dev;

  if (!priv->sdio_initialized)
    {
      return -ENODEV;
    }

  /* Check for new packet interrupt */

  if (!sdio_check_intr(hw, SDIO_INT_NEW_PACKET))
    {
      return 0;
    }

  /* Get packet length */

  len_from_slave = sdio_get_packet_len(hw);
  if (len_from_slave == 0)
    {
      return 0;
    }

  if (len_from_slave > ESP_RX_BUFFER_SIZE)
    {
      sdio_clear_intr(hw, 1 << SDIO_INT_NEW_PACKET);
      return -E2BIG;
    }

  /* Read header */

  ret = sdio_cmd53_read(hw, 1, ESP_SLAVE_CMD53_END_ADDR,
                        (uint8_t *)&hdr, ESP_PAYLOAD_HEADER_SIZE);
  if (ret < ESP_PAYLOAD_HEADER_SIZE)
    {
      return 0;
    }

  /* Validate header */

  if (hdr.len == 0 || hdr.offset != ESP_PAYLOAD_HEADER_SIZE ||
      hdr.len > max_len)
    {
      sdio_clear_intr(hw, 1 << SDIO_INT_NEW_PACKET);
      return 0;
    }

  /* Read payload */

  ret = sdio_cmd53_read(hw, 1,
                        ESP_SLAVE_CMD53_END_ADDR + hdr.offset,
                        data, hdr.len);

  /* Update RX byte count */

  sdio_update_rx_count(hw, len_from_slave);

  /* Clear interrupt */

  sdio_clear_intr(hw, 1 << SDIO_INT_NEW_PACKET);

  if (if_type)
    {
      *if_type = hdr.if_type;
    }

  if (if_num)
    {
      *if_num = hdr.if_num;
    }

  return hdr.len;
}

/****************************************************************************
 * Name: esp_hosted_init_protocol
 ****************************************************************************/

static int esp_hosted_init_protocol(struct esp_wifi_dev_s *priv)
{
  uint8_t mac_buf[6];
  int ret;
  sdmmc_dev_t *hw = (sdmmc_dev_t *)priv->hal.dev;

  /* Read MAC from scratch registers */

  ret = sdio_read_reg(hw, ESP_SLAVE_SCRATCH_REG_7, mac_buf, 6);
  if (ret >= 0 && (mac_buf[0] != 0 || mac_buf[1] != 0 || mac_buf[2] != 0))
    {
      memcpy(priv->mac, mac_buf, 6);
      WIFI_INFO("MAC: %02x:%02x:%02x:%02x:%02x:%02x\n",
                priv->mac[0], priv->mac[1], priv->mac[2],
                priv->mac[3], priv->mac[4], priv->mac[5]);
    }
  else
    {
      priv->mac[0] = 0x02;
      priv->mac[1] = 0x00;
      priv->mac[2] = 0x00;
      priv->mac[3] = 0x00;
      priv->mac[4] = 0x00;
      priv->mac[5] = 0x01;
    }

  return OK;
}

/****************************************************************************
 * Private Functions - Network Device Callbacks
 ****************************************************************************/

static int esp_wifi_ifup(FAR struct net_driver_s *dev)
{
  FAR struct esp_wifi_dev_s *priv =
    (FAR struct esp_wifi_dev_s *)dev->d_private;

  WIFI_INFO("Bringing up WiFi interface\n");

  if (!priv->sdio_initialized)
    {
      int ret = sdio_init_hw(priv);
      if (ret < 0)
        {
          WIFI_ERR("SDIO init failed: %d\n", ret);
          return ret;
        }

      esp_hosted_init_protocol(priv);
    }

  priv->ifup = true;
  work_queue(LPWORK, &priv->pollwork, esp_wifi_poll_work,
             priv, WIFI_POLL_INTERVAL);

  return OK;
}

static int esp_wifi_ifdown(FAR struct net_driver_s *dev)
{
  FAR struct esp_wifi_dev_s *priv =
    (FAR struct esp_wifi_dev_s *)dev->d_private;

  WIFI_INFO("Bringing down WiFi interface\n");
  work_cancel(LPWORK, &priv->pollwork);
  priv->ifup = false;
  priv->connected = false;
  netdev_carrier_off(dev);

  return OK;
}

static int esp_wifi_transmit(FAR struct net_driver_s *dev)
{
  FAR struct esp_wifi_dev_s *priv =
    (FAR struct esp_wifi_dev_s *)dev->d_private;
  int ret;

  ret = esp_hosted_send_packet(priv, ESP_STA_IF, 0,
                               dev->d_buf, dev->d_len);
  if (ret < 0)
    {
      WIFI_ERR("TX failed: %d\n", ret);
    }

  return ret;
}

static int esp_wifi_txavail(FAR struct net_driver_s *dev)
{
  if (dev->d_buf != NULL && dev->d_len > 0)
    {
      return esp_wifi_transmit(dev);
    }

  return OK;
}

