ret = sdmmc_send_cmd(hw, SD_CMD_SEND_OP_COND, 0, &resp, true);
WIFI_INFO("CMD5 ret=%d resp=0x%08lx\n", ret, (unsigned long)resp);
if (ret < 0)
  {
    WIFI_ERR("CMD5 failed - no SDIO card detected\n");
    return ret;
  }

/* Send CMD5 with voltage window */

ret = sdmmc_send_cmd(hw, SD_CMD_SEND_OP_COND, 0x00FF8000, &resp, true);
WIFI_INFO("CMD5 voltage ret=%d resp=0x%08lx\n", ret, (unsigned long)resp);
up_mdelay(10);

/* Send CMD3 (SEND_RELATIVE_ADDR) */

ret = sdmmc_send_cmd(hw, SD_CMD_SEND_RELATIVE_ADDR, 0, &resp, true);
WIFI_INFO("CMD3 ret=%d resp=0x%08lx\n", ret, (unsigned long)resp);
if (ret < 0)
  {
    WIFI_ERR("CMD3 failed\n");
    return ret;
  }

priv->rca = (resp >> 16) & 0xFFFF;
WIFI_INFO("CMD3 RCA=0x%04x\n", priv->rca);

/* Send CMD7 (SELECT_CARD) */

ret = sdmmc_send_cmd(hw, SD_CMD_SELECT_CARD,
                     ((uint32_t)priv->rca) << 16, &resp, true);
WIFI_INFO("CMD7 ret=%d resp=0x%08lx\n", ret, (unsigned long)resp);
if (ret < 0)
  {
    WIFI_ERR("CMD7 failed\n");
    return ret;
  }

/* Enable SDIO function 1 */

ret = sdio_cmd52_write(hw, 0, SD_IO_CCCR_FN_ENABLE, 0x02);
WIFI_INFO("Enable FN1 ret=%d\n", ret);

