static int esp_wifi_ifup(FAR struct net_driver_s *dev)
{
  FAR struct esp_wifi_dev_s *priv =
    (FAR struct esp_wifi_dev_s *)dev->d_private;
  int ret;

  WIFI_INFO("Bringing up WiFi interface\n");

  if (!priv->sdio_initialized)
    {
      ret = sdio_init_hw(priv);
      if (ret < 0)
        {
          WIFI_ERR("SDIO init failed: %d\n", ret);
          return ret;
        }

      ret = esp_hosted_init_protocol(priv);
      if (ret < 0)
        {
          WIFI_ERR("Protocol init failed: %d\n", ret);
          return ret;
        }
    }

  priv->ifup = true;
  work_queue(LPWORK, &priv->pollwork, esp_wifi_poll_work,
             priv, WIFI_POLL_INTERVAL);

  WIFI_INFO("WiFi interface up\n");
  return OK;
}

